INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-001', 'aws-aif', 'Uma equipe processa 40 milhões de registros uma vez por noite para gerar recomendações que serão exibidas no dia seguinte. Qual tipo de inferência é o adequado?',
  '[{"id":"A","text":"Inferência em lote"},{"id":"B","text":"Inferência em tempo real"},{"id":"C","text":"Inferência sem servidor"},{"id":"D","text":"Inferência assíncrona"}]'::jsonb, 'A',
  '{
    "summary": "O tipo de inferência é escolhido pelo perfil de consumo do resultado, não pelo volume.",
    "whyCorrect": "O resultado só é consumido no dia seguinte e o conjunto é fechado — é a definição de inferência em lote: a infraestrutura sobe, processa tudo e encerra, e você paga apenas o processamento.",
    "whyWrong": {
     "B": "Tempo real mantém endpoint vivo 24 horas para atender um trabalho que roda uma vez por noite. Quem escolhe esta alternativa está pensando no volume dos dados, e não em quem espera pela resposta — ninguém espera.",
     "C": "Sem servidor resolve tráfego intermitente de PEDIDOS individuais, cobrando por invocação. Quarenta milhões de invocações a tornam mais cara que o lote, e o raciocínio por trás dessa escolha costuma ser \"sem servidor é sempre mais barato\", que só vale para tráfego esporádico.",
     "D": "Assíncrona existe para carga grande com processamento demorado POR REQUISIÇÃO, mantendo endpoint e fila. Aqui não há requisição individual: confundir \"demora para responder\" com \"conjunto processado de madrugada\" é o erro exato que a alternativa testa."
    },
    "keyConcept": "Tipos de inferência: tempo real, lote, assíncrona e sem servidor",
    "compareWith": [
     "Inferência assíncrona vs sem servidor"
    ],
    "realWorldContext": "Recomendação noturna, cálculo de risco diário e enriquecimento de catálogo são os casos clássicos de lote."
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
