INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-002', 'aws-aif', 'Qual afirmação distingue corretamente IA generativa de IA agêntica?',
  '[{"id":"A","text":"São sinônimos; agêntica é o termo comercial de generativa"},{"id":"B","text":"Generativa produz conteúdo a partir de um pedido; agêntica planeja, usa ferramentas e executa passos até atingir um objetivo"},{"id":"C","text":"Agêntica funciona sem modelo de linguagem, usando apenas regras"},{"id":"D","text":"Generativa exige treinamento próprio; agêntica usa modelos prontos"}]'::jsonb, 'B',
  '{
    "summary": "A diferença é de AGÊNCIA: quem decide os próximos passos.",
    "whyCorrect": "Um sistema generativo responde ao que foi pedido. Um agêntico recebe um objetivo, decide quais ferramentas chamar, avalia o resultado e continua até concluir — planejamento, uso de ferramenta e orquestração são o que a AWS lista como conceitos de IA agêntica.",
    "whyWrong": {
     "A": "Tratar como sinônimo é o erro mais comum agora que o termo virou moda. A prova separa os dois explicitamente no enunciado de tarefa 1.1, e a distinção decide desenho de segurança: agente aciona ferramenta sozinho.",
     "C": "Inverte a realidade: o agente usa um modelo justamente para decidir. Sistema baseado só em regras é automação clássica, e chamá-lo de agêntico apaga o que há de novo.",
     "D": "Nenhuma das duas exige treinamento próprio. Essa alternativa confunde o eixo generativa-vs-agêntica com o eixo modelo-pronto-vs-treinado, que é uma classificação diferente."
    },
    "keyConcept": "IA generativa vs IA agêntica"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
