INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-003', 'aws-aif', 'Um banco precisa decidir, de forma auditável e com regra fixa, se um cliente pode sacar acima do limite diário. A regra é definida por política interna e muda por decreto da diretoria. Qual é a recomendação?',
  '[{"id":"A","text":"Treinar um modelo de classificação com o histórico de saques"},{"id":"B","text":"Usar um foundation model com prompt descrevendo a política"},{"id":"C","text":"Não usar ML: a regra é determinística e o requisito é um resultado específico, não uma previsão"},{"id":"D","text":"Usar detecção de anomalia não supervisionada"}]'::jsonb, 'C',
  '{
    "summary": "Reconhecer quando ML NÃO é a resposta é objetivo explícito do enunciado de tarefa 1.2.",
    "whyCorrect": "A política é conhecida, fixa e precisa ser auditável. ML produz previsão probabilística; aqui se exige um resultado específico e explicável linha a linha, que uma regra em código entrega com custo próximo de zero.",
    "whyWrong": {
     "A": "Treinar um classificador aprenderia o padrão histórico — inclusive erros passados — e produziria variação onde a política exige determinismo. É a alternativa que mais parece sofisticada e a que menos serve.",
     "B": "Um foundation model interpretando política em linguagem natural acrescenta não determinismo e custo por token a uma decisão que é um `if`. Além disso, mudança por decreto exigiria reescrever prompt em vez de alterar uma constante.",
     "D": "Detecção de anomalia responde \"isto é incomum?\", e a pergunta do negócio é \"isto é permitido?\". Confundir as duas é o erro de raciocínio que esta alternativa isola."
    },
    "keyConcept": "Quando ML não é apropriado",
    "realWorldContext": "Limite regulatório, cálculo de imposto e elegibilidade contratual são casos em que regra vence modelo.",
    "commonMistakes": "O enunciado dá o sinal na palavra \"auditável\" e em \"resultado específico\"."
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
