INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-004', 'aws-aif', 'Uma empresa quer transcrever ligações de atendimento em português e detectar o sentimento do cliente. Qual combinação de serviços gerenciados resolve com o menor esforço?',
  '[{"id":"A","text":"Amazon Polly e Amazon Translate"},{"id":"B","text":"Amazon Lex e Amazon Personalize"},{"id":"C","text":"Amazon Rekognition e Amazon Textract"},{"id":"D","text":"Amazon Transcribe e Amazon Comprehend"}]'::jsonb, 'D',
  '{
    "summary": "Cada serviço gerenciado de IA da AWS resolve uma modalidade específica, e a prova cobra o par correto.",
    "whyCorrect": "Transcribe converte fala em texto; Comprehend faz análise de sentimento e extração de entidades sobre texto. É a cadeia direta para o requisito.",
    "whyWrong": {
     "A": "Polly faz o caminho INVERSO — texto para fala — e Translate traduz idioma. Quem escolhe aqui trocou a direção da conversão, que é o erro mais comum entre Transcribe e Polly.",
     "B": "Lex constrói interface conversacional e Personalize faz recomendação. Nenhum dos dois transcreve áudio nem classifica sentimento; a escolha vem de associar \"atendimento\" a chatbot.",
     "C": "Rekognition trata imagem e vídeo, e Textract extrai texto de documento. Os dois são de visão, e a entrada aqui é áudio."
    },
    "keyConcept": "Serviços gerenciados de IA da AWS por modalidade",
    "compareWith": [
     "Transcribe vs Polly",
     "Comprehend vs Bedrock para análise de texto"
    ]
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
