INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-005', 'aws-aif', 'Um hospital precisa de um modelo cuja decisão possa ser justificada individualmente a um paciente e a um auditor. Que tipo de modelo tende a ser exigido pela restrição?',
  '[{"id":"A","text":"Um modelo tradicional interpretável, como regressão logística ou árvore"},{"id":"B","text":"Um foundation model grande, pela qualidade superior"},{"id":"C","text":"Um modelo de difusão"},{"id":"D","text":"Qualquer modelo, desde que a acurácia seja alta"}]'::jsonb, 'A',
  '{
    "summary": "Explicabilidade é critério de SELEÇÃO, e a prova lista isso como objetivo do enunciado 1.2.",
    "whyCorrect": "Regressão logística e árvores permitem apontar a contribuição de cada atributo para aquela decisão específica, que é o que uma justificativa individual exige em setor regulado.",
    "whyWrong": {
     "B": "Qualidade média maior não resolve a exigência: um modelo grande é difícil de explicar por decisão individual, e é justamente essa a restrição declarada. Escolher por desempenho quando o requisito é explicabilidade é o erro que a questão testa.",
     "C": "Modelos de difusão geram imagem e áudio; não são classificadores de decisão clínica. A alternativa existe para checar vocabulário.",
     "D": "Acurácia alta não produz justificativa. Esta é a alternativa mais tentadora porque é verdadeira em geral e irrelevante sob a restrição dada."
    },
    "keyConcept": "Modelo tradicional vs foundation model por requisito de explicabilidade",
    "realWorldContext": "Crédito, saúde e RH são os setores em que a exigência aparece por regulação."
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
