INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-006', 'aws-aif', 'Um conjunto tem imagens SEM rótulo e o objetivo é descobrir agrupamentos naturais de produtos parecidos. Que tipo de aprendizado é esse?',
  '[{"id":"A","text":"Supervisionado"},{"id":"B","text":"Não supervisionado"},{"id":"C","text":"Por reforço"},{"id":"D","text":"Por transferência"}]'::jsonb, 'B',
  '{
    "summary": "O tipo de aprendizado é definido pela presença ou ausência de rótulo e pela forma do sinal de treino.",
    "whyCorrect": "Sem rótulo e buscando estrutura natural nos dados, o problema é de agrupamento — aprendizado não supervisionado por definição.",
    "whyWrong": {
     "A": "Supervisionado exige rótulo, que o enunciado nega explicitamente. Quem marca esta alternativa está lendo \"classificar produtos\" como classificação supervisionada.",
     "C": "Por reforço aprende de recompensa em interação com um ambiente, o que não existe aqui — não há ação nem consequência.",
     "D": "Transferência é reaproveitar um modelo já treinado em outra tarefa; é uma TÉCNICA, não um tipo de aprendizado, e a questão pergunta o tipo."
    },
    "keyConcept": "Supervisionado, não supervisionado e por reforço"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
