INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-007', 'aws-aif', 'Qual métrica é a mais adequada quando deixar passar um caso positivo é muito mais caro que um alarme falso?',
  '[{"id":"A","text":"Precisão"},{"id":"B","text":"Acurácia"},{"id":"C","text":"Revocação"},{"id":"D","text":"Especificidade"}]'::jsonb, 'C',
  '{
    "summary": "A escolha da métrica é uma decisão de negócio: pergunte qual erro custa mais.",
    "whyCorrect": "Revocação mede quantos dos positivos existentes o modelo encontrou. Quando o falso negativo é o erro caro — deixar passar uma fraude, um diagnóstico ou uma falha —, é ela que precisa subir.",
    "whyWrong": {
     "A": "Precisão mede quantos dos apontados eram de fato positivos; ela protege contra falso POSITIVO, que é o erro barato neste cenário. Trocar as duas é o erro mais frequente do assunto.",
     "B": "Acurácia mistura os dois tipos de erro num número só e, com classe rara, fica alta mesmo num modelo inútil.",
     "D": "Especificidade olha a taxa de negativos corretamente identificados — de novo o lado do falso positivo, não o do falso negativo."
    },
    "keyConcept": "Precisão, revocação e o custo do erro",
    "compareWith": [
     "F1 quando os dois erros pesam"
    ]
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
