INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-008', 'aws-aif', 'O que MLOps acrescenta a um projeto de ML que já tem um modelo treinado e funcionando?',
  '[{"id":"A","text":"Aumenta a acurácia do modelo automaticamente"},{"id":"B","text":"Substitui a necessidade de conjunto de validação"},{"id":"C","text":"Elimina o custo de inferência"},{"id":"D","text":"Torna o processo repetível, monitorado e capaz de retreinar — trata o modelo como sistema, não como entregável"}]'::jsonb, 'D',
  '{
    "summary": "MLOps é sobre o CICLO, não sobre o modelo.",
    "whyCorrect": "Experimentação registrada, processo repetível, monitoramento e retreinamento são o que impedem que um modelo bom hoje se degrade sem ninguém perceber — é a diferença entre entregar um artefato e operar um sistema.",
    "whyWrong": {
     "A": "Nenhuma prática de operação melhora acurácia por si só; ela permite MEDIR a queda e reagir. Esperar ganho de acurácia é a expectativa errada mais comum ao adotar MLOps.",
     "B": "A validação continua indispensável — MLOps a torna automática e recorrente, não dispensável.",
     "C": "O custo de inferência é de infraestrutura e escolha de modo; MLOps ajuda a enxergá-lo, não a zerá-lo."
    },
    "keyConcept": "Fundamentos de MLOps"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
