INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-009', 'aws-aif', 'Uma equipe quer usar um modelo em produção sem operar servidores de inferência nem gerenciar escala. Qual abordagem descreve isso?',
  '[{"id":"A","text":"API gerenciada de um serviço como o Amazon Bedrock"},{"id":"B","text":"API própria hospedada em instâncias EC2 com balanceador"},{"id":"C","text":"Modelo embarcado no aplicativo móvel"},{"id":"D","text":"Execução manual em caderno quando necessário"}]'::jsonb, 'A',
  '{
    "summary": "O enunciado 1.3 pede distinguir API gerenciada de API auto-hospedada.",
    "whyCorrect": "Serviço gerenciado entrega o modelo por API sem que você provisione, escale ou aplique patch — a operação fica com o provedor, e você paga por uso.",
    "whyWrong": {
     "B": "É exatamente a definição de auto-hospedado: você opera instância, escala e disponibilidade. Escolher aqui é ignorar a restrição declarada no enunciado.",
     "C": "Embarcar no dispositivo resolve latência e privacidade, e traz um problema novo — distribuir atualização de modelo para cada aparelho.",
     "D": "Execução manual não é produção: não há disponibilidade, contrato de resposta nem rastreabilidade."
    },
    "keyConcept": "API gerenciada vs auto-hospedada"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
