INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-010', 'aws-aif', 'Qual par descreve corretamente dados estruturados e não estruturados para IA?',
  '[{"id":"A","text":"Imagem PNG e planilha de estoque"},{"id":"B","text":"Tabela de vendas em CSV e transcrição de ligação em texto livre"},{"id":"C","text":"Log JSON e tabela de banco relacional"},{"id":"D","text":"Vídeo MP4 e áudio WAV"}]'::jsonb, 'B',
  '{
    "summary": "Estruturado tem esquema fixo com campos definidos; não estruturado, não.",
    "whyCorrect": "Um CSV de vendas tem colunas tipadas e é estruturado; uma transcrição em texto livre não tem esquema e é não estruturada. O par ilustra os dois lados.",
    "whyWrong": {
     "A": "Está invertido na ordem: a imagem é a não estruturada e a planilha é a estruturada. A alternativa pune leitura apressada da ordem.",
     "C": "Os dois lados são estruturados ou semiestruturados — JSON tem esquema implícito e tabela tem esquema explícito. Não ilustra o contraste pedido.",
     "D": "Os dois são não estruturados, então também não contrastam."
    },
    "keyConcept": "Tipos de dado em IA"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
