INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-011', 'aws-aif', 'Uma varejista quer prever a demanda de cada SKU para as próximas 12 semanas. Que técnica de ML se aplica?',
  '[{"id":"A","text":"Classificação"},{"id":"B","text":"Agrupamento"},{"id":"C","text":"Regressão e previsão de série temporal"},{"id":"D","text":"Redução de dimensionalidade"}]'::jsonb, 'C',
  '{
    "summary": "A técnica sai da forma da SAÍDA desejada.",
    "whyCorrect": "A saída é um número contínuo ao longo do tempo — quantidade por semana —, o que é regressão sobre série temporal.",
    "whyWrong": {
     "A": "Classificação devolve categoria, e a pergunta pede quantidade. Quem escolhe aqui está pensando em \"alta, média ou baixa demanda\", que é uma reformulação do problema, não o problema dado.",
     "B": "Agrupamento encontra grupos sem rótulo; poderia agrupar SKUs semelhantes, mas não prevê quantidade.",
     "D": "Redução de dimensionalidade é etapa de preparação, não de previsão."
    },
    "keyConcept": "Regressão, classificação e agrupamento"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
