INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-012', 'aws-aif', 'Além das métricas do modelo, quais métricas de NEGÓCIO a prova espera que você considere ao avaliar uma solução de IA?',
  '[{"id":"A","text":"Apenas F1 e AUC"},{"id":"B","text":"Somente o tempo de treinamento"},{"id":"C","text":"Somente o número de parâmetros do modelo"},{"id":"D","text":"Custo por usuário, custo de desenvolvimento, retorno sobre o investimento e retorno do usuário"}]'::jsonb, 'D',
  '{
    "summary": "O enunciado 1.3 lista métricas de modelo E métricas de negócio, e cobra as duas.",
    "whyCorrect": "Custo por usuário, custo de desenvolvimento, retorno do investimento e retorno dado pelo cliente são os exemplos que o guia oficial nomeia — eles respondem se a solução vale, não se o modelo acerta.",
    "whyWrong": {
     "A": "F1 e AUC são métricas de MODELO. Ficar só nelas é o erro que a questão isola: um modelo excelente pode ter retorno negativo.",
     "B": "Tempo de treinamento é custo de desenvolvimento, uma parte pequena do quadro.",
     "C": "Número de parâmetros não é métrica de negócio nem de qualidade — é característica do modelo."
    },
    "keyConcept": "Métricas de modelo vs métricas de negócio"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
