INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-ai-ml-fundamentals-v2-013', 'aws-aif', 'Um modelo acerta 99% no conjunto de treino e 62% em dados novos. Como se chama isso, e qual é a leitura correta?',
  '[{"id":"A","text":"Sobreajuste; o modelo memorizou o treino e não generaliza"},{"id":"B","text":"Subajuste; o modelo é simples demais"},{"id":"C","text":"Viés de amostragem; o conjunto de teste está errado"},{"id":"D","text":"Deriva de conceito; o mundo mudou"}]'::jsonb, 'A',
  '{
    "summary": "A distância entre desempenho no treino e em dados novos é a assinatura do sobreajuste.",
    "whyCorrect": "Erro baixíssimo no treino com erro alto fora dele significa que o modelo decorou o conjunto em vez de aprender o padrão. As correções usuais são regularização, mais dados e parada antecipada.",
    "whyWrong": {
     "B": "Subajuste produz erro ALTO nos dois — o modelo nem no treino vai bem. A alternativa inverte a assinatura.",
     "C": "Viés de amostragem é uma causa possível de mau desempenho, mas não explica o abismo específico entre treino e teste; culpar o conjunto de teste é o reflexo de quem não quer revisar o modelo.",
     "D": "Deriva de conceito acontece ao longo do TEMPO, depois da implantação. Aqui o problema já existe na avaliação inicial."
    },
    "keyConcept": "Sobreajuste vs subajuste"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
