INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-001', 'aws-aif', 'Uma empresa quer que o assistente responda com base em documentos internos que mudam toda semana. Qual abordagem é a adequada e por quê?',
  '[{"id":"A","text":"RAG: recuperar os trechos relevantes no momento da pergunta e passá-los ao modelo"},{"id":"B","text":"Ajuste fino semanal do modelo com os documentos novos"},{"id":"C","text":"Pré-treinamento contínuo com o acervo completo"},{"id":"D","text":"Aumentar a temperatura para o modelo ser mais criativo"}]'::jsonb, 'A',
  '{
    "summary": "Conhecimento que muda com frequência pertence ao acervo recuperado, não aos pesos.",
    "whyCorrect": "RAG separa conhecimento de capacidade: atualizar o acervo é reindexar documento, o que acompanha uma mudança semanal com custo baixo e ainda permite citar a fonte.",
    "whyWrong": {
     "B": "Ajuste fino ensina FORMA e comportamento, não fatos atualizáveis. Refazer o ajuste toda semana é caro, lento e ainda deixa o modelo sem citar de onde veio a informação.",
     "C": "Pré-treinamento contínuo é ainda mais caro que ajuste fino e serve para adaptar o modelo a um domínio inteiro, não para manter fatos em dia.",
     "D": "Temperatura controla variação da amostragem. Aumentá-la em cima de informação desatualizada só torna o erro mais variado."
    },
    "keyConcept": "RAG vs ajuste fino para conhecimento que muda",
    "compareWith": [
     "Ajuste fino vs RAG vs aprendizado em contexto"
    ]
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
