INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-002', 'aws-aif', 'Quais serviços AWS podem armazenar embeddings como banco de vetores para um RAG?',
  '[{"id":"A","text":"Amazon SQS e Amazon SNS"},{"id":"B","text":"Amazon OpenSearch Service, Amazon Aurora e Amazon RDS para PostgreSQL"},{"id":"C","text":"AWS Glue e Amazon Athena"},{"id":"D","text":"Amazon Route 53 e CloudFront"}]'::jsonb, 'B',
  '{
    "summary": "O guia nomeia os serviços que armazenam embeddings em banco de vetores.",
    "whyCorrect": "OpenSearch Service, Aurora e RDS para PostgreSQL — este com pgvector — armazenam vetores e fazem busca por vizinho mais próximo, que é o que um RAG precisa. O Neptune entra no caso de grafo.",
    "whyWrong": {
     "A": "SQS e SNS são mensageria: transportam mensagem e não indexam vetor nem calculam semelhança.",
     "C": "Glue e Athena são ETL e consulta analítica sobre o lago. Podem preparar o dado antes de gerar embedding, mas não servem como índice vetorial de baixa latência.",
     "D": "Route 53 e CloudFront são DNS e rede de entrega. A alternativa existe para checar se o candidato associa \"busca rápida\" a cache de borda."
    },
    "keyConcept": "Bancos de vetores na AWS"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
