INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-003', 'aws-aif', 'Ordene do MENOR para o MAIOR custo típico de customização de um foundation model.',
  '[{"id":"A","text":"Pré-treinamento, ajuste fino, RAG, aprendizado em contexto"},{"id":"B","text":"RAG, aprendizado em contexto, pré-treinamento, ajuste fino"},{"id":"C","text":"Aprendizado em contexto, RAG, ajuste fino, pré-treinamento"},{"id":"D","text":"Ajuste fino, pré-treinamento, aprendizado em contexto, RAG"}]'::jsonb, 'C',
  '{
    "summary": "O guia cobra explicitamente o trade-off de custo entre as abordagens de customização.",
    "whyCorrect": "Aprendizado em contexto custa apenas os tokens do prompt; RAG acrescenta indexação e armazenamento; ajuste fino exige treino sobre dado rotulado; pré-treinamento é a construção do modelo, ordens de grandeza acima de todos.",
    "whyWrong": {
     "A": "Está exatamente invertida — coloca a opção mais cara primeiro. É a alternativa que pune leitura apressada do sentido da ordenação.",
     "B": "Inverte ajuste fino e pré-treinamento, que é o par com maior diferença de custo da lista, e ainda troca as duas primeiras.",
     "D": "Coloca ajuste fino como o mais barato, ignorando que ele exige dado rotulado, treino e ciclo de avaliação próprio."
    },
    "keyConcept": "Custo relativo das abordagens de customização"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
