INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-004', 'aws-aif', 'Qual técnica consiste em dar ao modelo alguns exemplos de entrada e saída dentro do próprio prompt?',
  '[{"id":"A","text":"Zero-shot"},{"id":"B","text":"Cadeia de pensamento"},{"id":"C","text":"Prompt negativo"},{"id":"D","text":"Few-shot"}]'::jsonb, 'D',
  '{
    "summary": "As técnicas de prompt têm nome próprio e a prova cobra a correspondência.",
    "whyCorrect": "Few-shot é justamente incluir alguns pares de exemplo no prompt, para que o modelo infira o formato e o critério esperados sem nenhum treinamento.",
    "whyWrong": {
     "A": "Zero-shot é o oposto: pedir a tarefa sem exemplo nenhum, contando apenas com a clareza da instrução. É a linha de base contra a qual se mede se os exemplos do few-shot valeram os tokens que custaram.",
     "B": "Cadeia de pensamento pede que o modelo exponha o raciocínio antes da resposta; é sobre o PROCESSO, não sobre fornecer exemplos.",
     "C": "Prompt negativo declara o que NÃO deve aparecer na saída, e não fornece exemplo do que se quer."
    },
    "keyConcept": "Técnicas de engenharia de prompt"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
