INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-006', 'aws-aif', 'Uma equipe mantém dezenas de versões de prompt e precisa controlar qual está em produção, com histórico. Que recurso do Bedrock endereça isso?',
  '[{"id":"A","text":"Bedrock Guardrails"},{"id":"B","text":"Bedrock Prompt Management"},{"id":"C","text":"Bedrock Knowledge Bases"},{"id":"D","text":"Bedrock Model Evaluation"}]'::jsonb, 'B',
  '{
    "summary": "O guia cita nominalmente versionamento e gestão de prompt com o Prompt Management.",
    "whyCorrect": "O Prompt Management guarda prompts como objetos versionados, com variáveis e implantação controlada — é a resposta para \"qual versão está em produção e o que mudou\".",
    "whyWrong": {
     "A": "Guardrails aplica política de conteúdo sobre entrada e saída; não versiona nem organiza prompt.",
     "C": "Knowledge Bases é o RAG gerenciado: ele versiona e indexa ACERVO DE DOCUMENTO, não texto de instrução. A confusão vem de os dois serem \"conteúdo que alimenta o modelo\", com ciclos de vida completamente diferentes.",
     "D": "Model Evaluation compara desempenho de modelos e prompts, o que é a etapa seguinte — mas não é onde a versão vive."
    },
    "keyConcept": "Bedrock Prompt Management"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
