INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-007', 'aws-aif', 'Qual é a diferença entre ajuste fino por instrução e pré-treinamento contínuo?',
  '[{"id":"A","text":"São sinônimos"},{"id":"B","text":"Pré-treinamento contínuo exige menos dado que o ajuste por instrução"},{"id":"C","text":"Ajuste por instrução ensina a seguir tarefas com pares de exemplo; pré-treinamento contínuo expõe o modelo a um corpus amplo de um domínio, sem rótulo"},{"id":"D","text":"Ajuste por instrução altera a arquitetura do modelo"}]'::jsonb, 'C',
  '{
    "summary": "As duas customizam pesos, mas com dado e objetivo diferentes.",
    "whyCorrect": "O ajuste por instrução usa pares de entrada e saída para ensinar comportamento em tarefas; o pré-treinamento contínuo usa texto corrido do domínio para impregnar vocabulário e padrões, sem rótulo.",
    "whyWrong": {
     "A": "Tratar como sinônimo faz escolher o dado errado: par rotulado num caso, corpus bruto no outro.",
     "B": "Está invertido — pré-treinamento contínuo costuma exigir MUITO mais dado, porque não tem o atalho do rótulo.",
     "D": "Nenhum dos dois muda a arquitetura: os dois ajustam PESOS de uma arquitetura já definida. Alterar arquitetura significaria treinar um modelo novo do zero, que é outra ordem de grandeza de custo."
    },
    "keyConcept": "Ajuste por instrução vs pré-treinamento contínuo"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
