INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-008', 'aws-aif', 'Sua equipe vai preparar dados para ajustar um foundation model. Qual conjunto de cuidados o guia enfatiza?',
  '[{"id":"A","text":"Apenas o volume: quanto mais exemplos, melhor"},{"id":"B","text":"Somente que os dados estejam em Parquet"},{"id":"C","text":"Somente que os dados sejam recentes"},{"id":"D","text":"Curadoria, governança, tamanho adequado, rotulagem e representatividade"}]'::jsonb, 'D',
  '{
    "summary": "O enunciado 3.3 lista explicitamente os cuidados de preparação de dado para ajuste.",
    "whyCorrect": "Curadoria, governança, tamanho, rotulagem e representatividade determinam se o ajuste ensina o padrão certo — e representatividade é o que evita que o modelo aprenda o viés de um recorte.",
    "whyWrong": {
     "A": "Volume sem curadoria amplifica ruído e viés; muitos exemplos ruins pioram o modelo em vez de melhorá-lo.",
     "B": "Formato de arquivo é detalhe de engenharia e não aparece entre os critérios de qualidade do ajuste.",
     "C": "Recência importa em alguns domínios e não substitui representatividade — dado recente e enviesado continua enviesado."
    },
    "keyConcept": "Preparação de dado para ajuste fino"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
