INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-009', 'aws-aif', 'Qual métrica é tipicamente usada para avaliar qualidade de RESUMO gerado por um modelo?',
  '[{"id":"A","text":"ROUGE"},{"id":"B","text":"BLEU"},{"id":"C","text":"RMSE"},{"id":"D","text":"AUC-ROC"}]'::jsonb, 'A',
  '{
    "summary": "Cada métrica de avaliação de linguagem tem um uso canônico, e a prova cobra o par.",
    "whyCorrect": "ROUGE mede sobreposição de conteúdo entre o texto gerado e um resumo de referência, focando em revocação — que é o que interessa num resumo: cobriu o que importava?",
    "whyWrong": {
     "B": "BLEU é a métrica canônica de TRADUÇÃO, focada em precisão de n-gramas. Trocar BLEU e ROUGE é o erro mais comum do assunto.",
     "C": "RMSE mede erro de regressão sobre valor numérico contínuo. Resumo é texto, e não existe subtração entre dois textos — aplicar RMSE aqui é levar métrica de um tipo de problema para outro.",
     "D": "AUC-ROC avalia classificação binária ao longo de todos os limiares possíveis. Não há classe nem limiar num resumo gerado, então a métrica não tem sobre o que operar."
    },
    "keyConcept": "ROUGE, BLEU e BERTScore",
    "compareWith": [
     "BERTScore e LLM-as-a-judge"
