INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-010', 'aws-aif', 'O que caracteriza a abordagem "LLM como juiz" na avaliação de saídas generativas?',
  '[{"id":"A","text":"Comparar a saída com uma resposta de referência palavra por palavra"},{"id":"B","text":"Usar um modelo para pontuar as saídas de outro segundo uma rubrica escrita"},{"id":"C","text":"Deixar o próprio modelo escolher qual resposta enviar ao usuário"},{"id":"D","text":"Medir a perplexidade do modelo no conjunto de teste"}]'::jsonb, 'B',
  '{
    "summary": "O guia lista LLM-as-a-judge entre as métricas relevantes de avaliação.",
    "whyCorrect": "Um modelo avaliador recebe a rubrica e pontua a saída, o que permite avaliar em escala aspectos que métrica de sobreposição não captura — como fidelidade à fonte e adequação de tom.",
    "whyWrong": {
     "A": "Comparação palavra por palavra é o que ROUGE e BLEU fazem; a diferença do juiz é justamente não depender de referência literal.",
     "C": "Escolher qual resposta enviar ao usuário é roteamento em tempo de execução — decisão de produto. Avaliação acontece antes e fora do caminho da requisição, para decidir o que colocar em produção.",
     "D": "Perplexidade mede o quanto o modelo se surpreende com o texto, e não se a resposta serve ao objetivo."
    },
    "keyConcept": "LLM como juiz"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
