INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-011', 'aws-aif', 'Qual é o papel de um agente de IA numa aplicação, segundo o guia?',
  '[{"id":"A","text":"Substituir o modelo de linguagem por regras determinísticas"},{"id":"B","text":"Comprimir o prompt para reduzir custo"},{"id":"C","text":"Receber um objetivo e, com autonomia, planejar e usar ferramentas para alcançá-lo"},{"id":"D","text":"Armazenar embeddings do acervo"}]'::jsonb, 'C',
  '{
    "summary": "O enunciado 3.1 pede definir o papel dos agentes e suas aplicações de negócio.",
    "whyCorrect": "O agente recebe um objetivo, decide os passos, aciona ferramentas e avalia resultados até concluir — é o que o diferencia de uma única chamada de geração.",
    "whyWrong": {
     "A": "O agente USA o modelo justamente para decidir o próximo passo; trocá-lo por regras determinísticas elimina a agência que o define e devolve o sistema à automação clássica, que já existia.",
     "B": "Compressão de prompt é técnica de engenharia de contexto, voltada a custo e a caber na janela. Ela pode aparecer dentro de um agente, mas não é o que define o papel dele na aplicação.",
     "D": "Armazenar embedding é papel do banco de vetores dentro de um RAG — infraestrutura de recuperação. Confundir com agente vem de os dois aparecerem no mesmo diagrama de solução de IA."
    },
    "keyConcept": "Papel dos agentes de IA"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
