INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-012', 'aws-aif', 'Um caso de uso exige respostas em até 300 milissegundos e tolera qualidade um pouco menor. Que critério de seleção domina?',
  '[{"id":"A","text":"Tamanho da janela de contexto"},{"id":"B","text":"Suporte multimodal"},{"id":"C","text":"Capacidade de ajuste fino"},{"id":"D","text":"Latência, o que costuma levar a um modelo menor"}]'::jsonb, 'D',
  '{
    "summary": "Quando o enunciado nomeia uma restrição, ela é o eixo a otimizar.",
    "whyCorrect": "Um teto de 300 ms com tolerância a perda de qualidade aponta diretamente para modelo menor e mais rápido — latência é critério de seleção listado no guia.",
    "whyWrong": {
     "A": "Janela grande não ajuda a responder rápido e, em geral, vem com modelos maiores e mais lentos.",
     "B": "Multimodalidade só importa se a entrada ou a saída tiver imagem, áudio ou vídeo, e o cenário não menciona nenhuma delas. Escolher um critério que o enunciado não cita é o erro que a questão isola.",
     "C": "Ajuste fino é sobre customização e acrescenta um ciclo de trabalho; não é o que atende um teto de latência."
    },
    "keyConcept": "Latência como critério de escolha de modelo"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
