INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-013', 'aws-aif', 'O que é destilação de modelo e qual é o ganho principal?',
  '[{"id":"A","text":"Treinar um modelo menor para reproduzir o comportamento de um maior, reduzindo custo e latência"},{"id":"B","text":"Remover camadas aleatoriamente para acelerar a inferência"},{"id":"C","text":"Comprimir os pesos sem perda para ocupar menos disco"},{"id":"D","text":"Dividir o modelo entre várias GPUs"}]'::jsonb, 'A',
  '{
    "summary": "Destilação aparece entre as abordagens de customização e no trade-off de custo.",
    "whyCorrect": "Um modelo pequeno é treinado a partir das saídas de um grande, herdando parte do comportamento a uma fração do custo por chamada e com latência menor.",
    "whyWrong": {
     "B": "Remover camadas ao acaso é poda mal feita e degrada o modelo sem o processo de transferência que a destilação faz.",
     "C": "Compressão de pesos sem perda é quantização e formato de armazenamento, e não envolve treinar um modelo novo.",
     "D": "Dividir entre GPUs é paralelismo de modelo, uma técnica de infraestrutura de treino ou inferência."
    },
    "keyConcept": "Destilação de modelo"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
