INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-014', 'aws-aif', 'Como avaliar uma aplicação de RAG, e não apenas o modelo isolado?',
  '[{"id":"A","text":"Medir só a fluência do texto gerado"},{"id":"B","text":"Medir recuperação e geração separadamente: o trecho certo foi recuperado, e a resposta se sustenta nele"},{"id":"C","text":"Medir apenas a latência de ponta a ponta"},{"id":"D","text":"Comparar o número de tokens de entrada e saída"}]'::jsonb, 'B',
  '{
    "summary": "O guia pede avaliar aplicações construídas com FM — RAG, agentes e fluxos —, não só o modelo.",
    "whyCorrect": "Um RAG falha em dois lugares distintos: não recuperar o trecho certo, ou recuperar e responder sem se apoiar nele. Medir os dois separadamente é o que diz onde investir.",
    "whyWrong": {
     "A": "Fluência é a parte que o modelo faz bem mesmo quando a resposta está errada — é exatamente o que engana em avaliação superficial.",
     "C": "Latência de ponta a ponta é requisito operacional legítimo e não diz nada sobre a resposta estar certa. Um RAG que erra rápido continua errando — medir só o tempo dá a sensação de rigor sem nenhum.",
     "D": "Contagem de tokens de entrada e saída mede CUSTO, e é um número importante — mas responder barato e errado não é melhor que responder caro e certo. A questão pede avaliação de qualidade."
    },
    "keyConcept": "Avaliação de aplicações de RAG"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
