INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-015', 'aws-aif', 'Qual prática melhora de forma consistente a qualidade da resposta, segundo as boas práticas listadas?',
  '[{"id":"A","text":"Escrever o prompt mais longo possível"},{"id":"B","text":"Repetir a mesma instrução várias vezes"},{"id":"C","text":"Ser específico e conciso, com contexto claro e formato de saída declarado"},{"id":"D","text":"Usar sempre a temperatura máxima"}]'::jsonb, 'C',
  '{
    "summary": "O guia lista especificidade e concisão entre as boas práticas de prompt.",
    "whyCorrect": "Instrução específica, contexto suficiente e formato de saída declarado reduzem a ambiguidade que o modelo teria de resolver adivinhando — é o ganho mais barato e mais consistente.",
    "whyWrong": {
     "A": "Prompt longo dilui a instrução no meio do texto, onde a atenção do modelo é mais fraca, e ainda aumenta o custo de entrada em toda chamada. Comprimento é o proxy errado para esforço de engenharia.",
     "B": "Repetição ajuda em contexto muito longo, onde a instrução final se distancia — como prática geral, ela só ocupa espaço.",
     "D": "Temperatura máxima aumenta a variação da amostragem, o que piora justamente as tarefas que exigem resposta consistente — classificação, extração e qualquer saída que alimente código."
    },
    "keyConcept": "Boas práticas de engenharia de prompt"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
