INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-016', 'aws-aif', 'Uma aplicação precisa gerar respostas ancoradas em documentos e CITAR a fonte de cada afirmação. Qual recurso entrega isso de forma gerenciada?',
  '[{"id":"A","text":"Amazon Comprehend"},{"id":"B","text":"Amazon Polly"},{"id":"C","text":"AWS Lambda com um prompt maior"},{"id":"D","text":"Amazon Bedrock Knowledge Bases com RetrieveAndGenerate"}]'::jsonb, 'D',
  '{
    "summary": "Citação de fonte é característica do RAG gerenciado do Bedrock.",
    "whyCorrect": "O Knowledge Bases devolve a resposta junto com as referências dos trechos usados, o que atende ao requisito de citação sem que você construa o pipeline de atribuição.",
    "whyWrong": {
     "A": "Comprehend extrai entidade, sentimento e tópico de um texto que você já tem. Ele analisa, não gera resposta nem recupera documento — e portanto não tem de onde tirar uma citação.",
     "B": "Polly sintetiza voz a partir de texto: é saída de áudio, uma modalidade diferente do problema. Ele poderia ler em voz alta a resposta pronta, sem participar em nada de produzi-la.",
     "C": "Colocar o documento inteiro num prompt maior não produz citação verificável, além de estourar custo e janela conforme o acervo cresce."
    },
    "keyConcept": "Citação de fonte em RAG gerenciado"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
