INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-017', 'aws-aif', 'Quando a avaliação com humano no laço é preferível a métricas automáticas?',
  '[{"id":"A","text":"Quando o critério é subjetivo — tom, utilidade, adequação — e nenhuma referência literal captura isso"},{"id":"B","text":"Sempre, porque humano é mais confiável"},{"id":"C","text":"Nunca, porque não escala"},{"id":"D","text":"Apenas para medir latência"}]'::jsonb, 'A',
  '{
    "summary": "O guia lista avaliação com humano no laço entre as abordagens válidas.",
    "whyCorrect": "Tom, utilidade e adequação ao público não têm resposta de referência única, e é aí que o julgamento humano capta o que ROUGE e BLEU não medem. O custo se administra amostrando.",
    "whyWrong": {
     "B": "\"Sempre\" ignora o custo e a inconsistência entre avaliadores; para critério objetivo, a métrica automática é mais barata e mais estável.",
     "C": "\"Nunca\" descarta a única forma de avaliar critério subjetivo — e escala se resolve com amostragem, não com abandono.",
     "D": "Latência se mede por instrumentação automática, com precisão de milissegundos e custo zero. Gastar tempo de avaliador humano nisso é usar o recurso mais caro para medir o que uma métrica já dá de graça."
    },
    "keyConcept": "Avaliação com humano no laço"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
