INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-foundation-model-apps-v1-018', 'aws-aif', 'Um prompt de extração devolve, às vezes, um campo que não existe no documento. Qual ajuste ataca a causa?',
  '[{"id":"A","text":"Aumentar o número de exemplos few-shot"},{"id":"B","text":"Declarar explicitamente o que fazer quando o campo não existir — devolver nulo e não inferir"},{"id":"C","text":"Reduzir a janela de contexto"},{"id":"D","text":"Trocar para um modelo maior"}]'::jsonb, 'B',
  '{
    "summary": "Sem critério de parada, o comportamento padrão de um modelo é preencher a lacuna.",
    "whyCorrect": "Você pediu um campo e não disse o que fazer na ausência dele. A instrução literal de devolver nulo e não inferir custa uma linha e elimina a classe inteira de erro.",
    "whyWrong": {
     "A": "Mais exemplos ajudam no formato e não tratam o caso ausente, a menos que um dos exemplos mostre justamente a ausência — o que é a mesma correção, escrita de outro jeito e mais caro.",
     "C": "Reduzir a janela pode até cortar a informação necessária e piorar o resultado; não tem relação com inventar campo.",
     "D": "Modelo maior diminui a frequência e não elimina a causa, além de encarecer toda chamada para tratar um caso de borda."
    },
    "keyConcept": "Critério de parada em prompt de extração"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
