INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-001', 'aws-aif', 'Uma equipe de fintech precisa classificar transações como ''fraude'' ou ''legítima'' com base em um histórico rotulado de 2 milhões de transações com a coluna is_fraud já preenchida. Qual paradigma de aprendizado é o mais apropriado?',
  '[{"id":"A","text":"Aprendizado supervisionado — classificação binária"},{"id":"B","text":"Aprendizado não supervisionado (clustering)"},{"id":"C","text":"Aprendizado por reforço com recompensa esparsa"},{"id":"D","text":"Self-supervised learning com pretext tasks"}]'::jsonb, 'A',
  '{
    "summary": "Dados rotulados + saída categórica = classificação supervisionada.",
    "whyCorrect": "Existe um label (is_fraud) com 2 classes (0/1) — o modelo aprende a mapear features de transação para a classe usando exemplos históricos rotulados. Esse é o caso clássico de aprendizado supervisionado, especificamente classificação binária.",
    "whyWrong": {
     "B": "Clustering é não supervisionado — descobre agrupamentos sem labels. Aqui já temos o label, então jogá-lo fora desperdiça informação valiosa.",
     "C": "Reinforcement learning serve para sequência de decisões com recompensa diferida (jogos, robótica). Não há agente interagindo com ambiente aqui.",
     "D": "Self-supervised gera labels a partir do próprio dado (ex: prever palavra mascarada). Não faz sentido quando o label real já existe."
    },
    "keyConcept": "Supervised vs Unsupervised vs Reinforcement Learning — escolha pelo tipo de dado disponível",
    "compareWith": [
     "Classification vs Regression (categórica vs contínua)",
     "Binary vs Multi-class classification"
    ],
    "realWorldContext": "Fraude em cartão de crédito é o exemplo canônico — Nubank, Stripe e PayPal usam classificadores supervisionados em produção.",
    "commonMistakes": "Confundir ''detecção de anomalia não supervisionada'' com classificação supervisionada. Se há label, prefira supervisionado — anomaly detection só quando o evento raro nunca foi observado.",
    "tutorSeeds": [
     "Quando faz sentido tratar fraude como anomaly detection em vez de classificação?",
     "Como lidar com o desbalanceamento típico de fraude (1:1000)?"
    ]
   }'::jsonb,
  'Supervised Learning', 'Fundamentals of AI and ML', 'easy', 'scenario', '["supervised-learning","classification","fraud-detection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
