INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-002', 'aws-aif', 'Qual a diferença fundamental entre Inteligência Artificial (AI), Machine Learning (ML) e Deep Learning (DL)?',
  '[{"id":"A","text":"São sinônimos usados em contextos diferentes"},{"id":"B","text":"AI ⊃ ML ⊃ DL — DL é um subconjunto de ML que usa redes neurais profundas, e ML é um subconjunto de AI"},{"id":"C","text":"DL ⊃ ML ⊃ AI — DL é o conceito mais amplo"},{"id":"D","text":"AI é sempre baseado em regras, ML é estatístico, DL é probabilístico"}]'::jsonb, 'B',
  '{
    "summary": "AI é o campo amplo; ML é a subdisciplina que aprende com dados; DL é o subset de ML com redes neurais multi-camadas.",
    "whyCorrect": "Hierarquia correta: AI engloba qualquer sistema que simule inteligência (inclui regras, árvores de decisão, busca, ML). ML é o ramo da AI que aprende padrões a partir de dados sem regras explícitas. DL é o ramo do ML que usa redes neurais com múltiplas camadas (profundas) para representação automática de features.",
    "whyWrong": {
     "A": "Não são sinônimos — há diferença técnica clara. Sistemas baseados em regras (expert systems) são AI mas não são ML.",
     "C": "Hierarquia invertida — DL é o subconjunto mais específico, não o mais amplo.",
     "D": "AI não é ''sempre baseado em regras'' — inclui ML e DL. ML não é só estatístico — inclui métodos como árvores e instance-based."
    },
    "keyConcept": "Hierarquia AI ⊃ ML ⊃ DL ⊃ GenAI (Generative AI é subset de DL focado em geração)",
    "compareWith": [
     "Symbolic AI (regras) vs Statistical AI (ML)",
     "Classical ML (árvores, SVM) vs Deep Learning (neural nets)"
    ],
    "realWorldContext": "Em uma entrevista AWS, distinguir esses termos é eliminação imediata. Os AWS services Rekognition/Translate são DL; Forecast usa mix de ML clássico + DL.",
    "commonMistakes": "Chamar qualquer chatbot de ''AI'' sem distinguir se é rule-based (regex) ou LLM (DL).",
    "tutorSeeds": [
     "Onde Generative AI se encaixa nessa hierarquia?",
     "Quais AWS AI Services usam DL por trás?"
    ]
   }'::jsonb,
  'AI vs ML vs Deep Learning', 'Fundamentals of AI and ML', 'easy', 'recall', '["ai-fundamentals","definitions","deep-learning"]'::jsonb, 'ai-draft', 'active', now(), now()
)
