INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-003', 'aws-aif', 'Uma startup de e-commerce quer agrupar clientes em segmentos de comportamento de compra para uma campanha de marketing direcionada, mas não possui categorias pré-definidas — quer DESCOBRIR os grupos. Qual técnica é a mais adequada?',
  '[{"id":"A","text":"Regressão logística multiclasse"},{"id":"B","text":"Random Forest classifier"},{"id":"C","text":"Clustering com k-means"},{"id":"D","text":"XGBoost com objetivo multi-class softmax"}]'::jsonb, 'C',
  '{
    "summary": "Descobrir grupos sem labels prévios = clustering (não supervisionado).",
    "whyCorrect": "K-means é o algoritmo clássico de clustering: agrupa pontos em k clusters minimizando a distância intra-cluster. Como não existem categorias pré-definidas, o problema é não supervisionado por natureza — k-means é exatamente isso.",
    "whyWrong": {
     "A": "Regressão logística é supervisionada — exige label. Não existem labels aqui.",
     "B": "Random Forest classifier é supervisionado — também exige label.",
     "D": "XGBoost multi-class exige labels — você teria que primeiro definir as classes, que é justamente o que NÃO temos."
    },
    "keyConcept": "Clustering (não supervisionado) vs Classification (supervisionado)",
    "compareWith": [
     "K-means vs Hierarchical clustering vs DBSCAN",
     "Customer segmentation via k-means vs via regras de negócio"
    ],
    "realWorldContext": "Segmentação RFM (Recency, Frequency, Monetary) clusterizada por k-means é padrão em retail/e-commerce.",
    "commonMistakes": "Escolher k arbitrariamente — use elbow method ou silhouette score para definir k.",
    "tutorSeeds": [
     "Como decidir o número de clusters k?",
     "Quando hierarchical clustering é preferível ao k-means?"
    ]
   }'::jsonb,
  'Unsupervised Learning', 'Fundamentals of AI and ML', 'easy', 'scenario', '["clustering","k-means","unsupervised","segmentation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
