INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-004', 'aws-aif', 'Uma equipe treinou um modelo de classificação de imagens com 99% de acurácia no conjunto de treino, mas apenas 62% no conjunto de teste. Qual é o diagnóstico mais provável?',
  '[{"id":"A","text":"Underfitting — modelo simples demais"},{"id":"B","text":"Data leakage — labels vazaram para as features"},{"id":"C","text":"Modelo está perfeito — gap é normal"},{"id":"D","text":"Overfitting — modelo memorizou o treino mas não generaliza"}]'::jsonb, 'D',
  '{
    "summary": "Acurácia alta no treino e baixa no teste = overfitting clássico.",
    "whyCorrect": "Quando um modelo memoriza o treino (99%) mas falha em dados novos (62%), ele aprendeu padrões espúrios do conjunto de treino que não generalizam. Esse gap grande entre treino e teste é a assinatura do overfitting. Soluções: regularização (L1/L2, dropout), mais dados, data augmentation, modelo mais simples, early stopping.",
    "whyWrong": {
     "A": "Underfitting daria acurácia BAIXA em AMBOS — ex: 60% treino e 58% teste. Aqui o treino está 99%, então o modelo aprendeu, mas demais.",
     "B": "Data leakage normalmente dá acurácia altíssima em AMBOS conjuntos (ex: 99% treino + 98% teste), porque o leak está em ambos. Não explica o gap.",
     "C": "Gap de 37 pontos é gigante — não é normal. Em produção, esse modelo terá desempenho ruim."
    },
    "keyConcept": "Overfitting — alta variância, baixa generalização",
    "compareWith": [
     "Overfitting vs Underfitting (bias-variance trade-off)",
     "Regularização L1 vs L2 vs Dropout"
    ],
    "realWorldContext": "Visão computacional com poucos dados rotulados é vulnerável a overfitting — data augmentation (rotação, flip, crop) é receita padrão.",
    "commonMistakes": "Confundir overfitting com data leakage. Se test acc também está alta, suspeite de leak.",
    "tutorSeeds": [
     "Como diferenciar overfitting de data leakage na prática?",
     "Qual técnica de regularização escolher primeiro?"
    ]
   }'::jsonb,
  'Overfitting and Underfitting', 'Fundamentals of AI and ML', 'easy', 'troubleshoot', '["overfitting","generalization","regularization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
