INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-005', 'aws-aif', 'Em uma matriz de confusão de um classificador binário (positivo = fraude), há 50 TP, 10 FP, 5 FN e 935 TN. Qual é a precision do modelo?',
  '[{"id":"A","text":"50 / (50 + 10) = 0,833"},{"id":"B","text":"50 / (50 + 5) = 0,909"},{"id":"C","text":"50 / 1000 = 0,050"},{"id":"D","text":"(50 + 935) / 1000 = 0,985"}]'::jsonb, 'A',
  '{
    "summary": "Precision = TP / (TP + FP) — entre os preditos positivos, quantos realmente são.",
    "whyCorrect": "Precision mede a qualidade dos positivos previstos. Fórmula: TP / (TP + FP) = 50 / (50+10) = 50/60 = 0,833. Responde: ''das transações que classifiquei como fraude, quantas são fraude de verdade?''",
    "whyWrong": {
     "B": "50/(50+5) = 0,909 é Recall (TP / (TP+FN)) — ''das fraudes reais, quantas peguei?''. Não é precision.",
     "C": "50/1000 = 0,05 é a prevalência da classe positiva no dataset, não precision.",
     "D": "(50+935)/1000 = 0,985 é Accuracy — frações dos acertos totais. Enganosa em dataset desbalanceado."
    },
    "keyConcept": "Precision = TP/(TP+FP), Recall = TP/(TP+FN), F1 = média harmônica",
    "compareWith": [
     "Precision (qualidade) vs Recall (cobertura)",
     "Accuracy enganosa em classes desbalanceadas"
    ],
    "realWorldContext": "Em fraude, recall alto pode importar mais (não deixar fraude passar), mesmo que precision caia (mais falsos alarmes para investigar).",
    "commonMistakes": "Confundir precision com accuracy. Em problema desbalanceado (1% fraude), um modelo que sempre prevê ''não fraude'' tem 99% de accuracy e 0% de recall.",
    "tutorSeeds": [
     "Por que F1 é preferível a accuracy em classes desbalanceadas?",
     "Quando vale otimizar recall em detrimento de precision?"
    ]
   }'::jsonb,
  'Model Evaluation Metrics', 'Fundamentals of AI and ML', 'medium', 'scenario', '["precision","recall","confusion-matrix","metrics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
