INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-006', 'aws-aif', 'Uma equipe está prevendo o PREÇO de venda de imóveis com base em features (área, quartos, bairro, idade). Qual tipo de tarefa de ML é essa e qual métrica de avaliação é adequada?',
  '[{"id":"A","text":"Classificação multiclasse — métrica F1-macro"},{"id":"B","text":"Regressão — métrica RMSE ou MAE"},{"id":"C","text":"Clustering — métrica silhouette score"},{"id":"D","text":"Classificação binária — métrica ROC-AUC"}]'::jsonb, 'B',
  '{
    "summary": "Saída contínua (preço em R$) = regressão. Métricas: RMSE, MAE, R².",
    "whyCorrect": "O alvo (preço) é uma variável contínua de valor real (ex: R$ 450.000,00), portanto a tarefa é regressão. As métricas adequadas são MAE (erro absoluto médio — interpretável em R$), RMSE (penaliza erros grandes mais fortemente) e R² (variância explicada).",
    "whyWrong": {
     "A": "Classificação seria se o output fosse categórico (''barato'' / ''médio'' / ''caro''). Preço bruto é contínuo.",
     "C": "Clustering não tem alvo a prever — agrupa sem label. Aqui há um alvo claro (preço).",
     "D": "Classificação binária seria ''vai vender ou não''. Prever o valor numérico é regressão."
    },
    "keyConcept": "Regression — target contínuo; métricas: MAE, RMSE, MAPE, R²",
    "compareWith": [
     "MAE (linear) vs RMSE (penaliza outliers) vs MAPE (percentual)",
     "Linear Regression vs XGBoost Regressor vs Neural Network"
    ],
    "realWorldContext": "Zillow, QuintoAndar e Loft usam modelos de regressão (gradient boosting é estado da arte) para preço de imóvel.",
    "commonMistakes": "Usar accuracy/F1 em problema de regressão — não fazem sentido em saída contínua.",
    "tutorSeeds": [
     "Quando RMSE é preferível a MAE?",
     "Como interpretar R² negativo?"
    ]
   }'::jsonb,
  'Regression', 'Fundamentals of AI and ML', 'easy', 'scenario', '["regression","rmse","mae","house-prices"]'::jsonb, 'ai-draft', 'active', now(), now()
)
