INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-007', 'aws-aif', 'Em um problema de classificação de doenças raras (incidência de 0,5% na população), um modelo apresenta 99,5% de accuracy. Por que essa métrica pode ser enganosa?',
  '[{"id":"A","text":"Accuracy não funciona em problemas de classificação"},{"id":"B","text":"Accuracy só funciona em regressão"},{"id":"C","text":"Um classificador trivial que sempre prevê ''sem doença'' já atinge 99,5% — accuracy não revela se o modelo detecta a classe minoritária"},{"id":"D","text":"Accuracy precisa ser sempre 100% para ser confiável"}]'::jsonb, 'C',
  '{
    "summary": "Em dataset desbalanceado, accuracy reflete a classe majoritária e esconde falha na minoritária.",
    "whyCorrect": "Com 0,5% de doentes, se o modelo prever sempre ''saudável'', acerta os 99,5% sem doença e erra os 0,5% doentes — resultado: accuracy = 99,5% e recall da classe positiva = 0%. Métricas adequadas: precision, recall, F1, ROC-AUC, PR-AUC e confusion matrix.",
    "whyWrong": {
     "A": "Accuracy funciona em classificação — só não é informativa em datasets muito desbalanceados.",
     "B": "Accuracy é métrica de classificação, não de regressão. Regressão usa MAE/RMSE.",
     "D": "Não precisa ser 100% — o problema é a interpretação, não o valor absoluto."
    },
    "keyConcept": "Accuracy paradox em dados desbalanceados — usar recall/F1/PR-AUC",
    "compareWith": [
     "Accuracy vs Balanced Accuracy",
     "ROC-AUC vs PR-AUC (PR-AUC melhor em forte desbalanceamento)"
    ],
    "realWorldContext": "Câncer raro, fraude, churn, detecção de defeitos — todos com classe positiva <5%, todos sofrem accuracy paradox.",
    "commonMistakes": "Reportar accuracy alta em problema desbalanceado sem mostrar recall/F1 da classe rara.",
    "tutorSeeds": [
     "Quando PR-AUC é preferível a ROC-AUC?",
     "Como SMOTE ajuda em desbalanceamento?"
    ]
   }'::jsonb,
  'Class Imbalance', 'Fundamentals of AI and ML', 'medium', 'scenario', '["class-imbalance","accuracy-paradox","metrics","healthcare"]'::jsonb, 'ai-draft', 'active', now(), now()
)
