INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-008', 'aws-aif', 'Qual algoritmo built-in do SageMaker é OTIMIZADO para problemas tabulares (tabela CSV/Parquet) de classificação e regressão, frequentemente vencedor em competições Kaggle?',
  '[{"id":"A","text":"BlazingText"},{"id":"B","text":"Object2Vec"},{"id":"C","text":"Semantic Segmentation"},{"id":"D","text":"XGBoost"}]'::jsonb, 'D',
  '{
    "summary": "XGBoost é o algoritmo de gradient boosting padrão para dados tabulares.",
    "whyCorrect": "XGBoost (eXtreme Gradient Boosting) é um algoritmo de ensemble de árvores de decisão com gradient boosting otimizado. Domina problemas tabulares — classificação binária, multiclasse e regressão. O SageMaker oferece XGBoost como built-in algorithm com suporte a treinamento distribuído.",
    "whyWrong": {
     "A": "BlazingText é otimizado para NLP — word2vec e classificação de texto, não tabular.",
     "B": "Object2Vec gera embeddings para pares de objetos — recomendações, similaridade entre documentos. Não é tabular padrão.",
     "C": "Semantic Segmentation é para visão computacional — segmentação de imagem por pixel. Nada a ver com tabular."
    },
    "keyConcept": "SageMaker built-in algorithms — XGBoost (tabular), BlazingText (NLP), Image Classification (CV)",
    "compareWith": [
     "XGBoost vs LightGBM vs CatBoost",
     "XGBoost vs Linear Learner (SageMaker)"
    ],
    "realWorldContext": "XGBoost é o cavalo-de-batalha de qualquer ML team em produção: scoring de crédito, churn, previsão de demanda.",
    "commonMistakes": "Tentar usar Neural Networks em dados tabulares pequenos — XGBoost geralmente vence até 100k linhas.",
    "tutorSeeds": [
     "Por que XGBoost vence Neural Networks em dados tabulares pequenos?",
     "Quando usar Linear Learner em vez de XGBoost?"
    ]
   }'::jsonb,
  'SageMaker Built-in Algorithms', 'Fundamentals of AI and ML', 'easy', 'recall', '["sagemaker","xgboost","tabular","gradient-boosting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
