INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-009', 'aws-aif', 'Uma empresa precisa transcrever 10 mil horas de áudio de ligações de call center para português brasileiro e gerar texto pesquisável. Qual serviço AWS é o mais adequado SEM precisar treinar modelo?',
  '[{"id":"A","text":"Amazon Transcribe"},{"id":"B","text":"Amazon Polly"},{"id":"C","text":"Amazon Comprehend"},{"id":"D","text":"Amazon Translate"}]'::jsonb, 'A',
  '{
    "summary": "Áudio → texto = Amazon Transcribe (speech-to-text).",
    "whyCorrect": "Amazon Transcribe é o serviço gerenciado de Automatic Speech Recognition (ASR) da AWS. Suporta pt-BR, diarização de falantes, vocabulário customizado, channel identification (separar agente vs cliente). Não precisa treinar — chamada de API direta.",
    "whyWrong": {
     "B": "Polly é o OPOSTO — text-to-speech (texto → voz). Você quer o caminho contrário.",
     "C": "Comprehend faz NLP em TEXTO (NER, sentimento). Precisa do texto já transcrito como entrada — viria depois do Transcribe.",
     "D": "Translate faz tradução entre idiomas — não converte áudio em texto."
    },
    "keyConcept": "AWS AI Services — Transcribe (ASR), Polly (TTS), Translate (MT), Comprehend (NLP)",
    "compareWith": [
     "Amazon Transcribe vs Transcribe Medical vs Transcribe Call Analytics",
     "Real-time streaming vs Batch transcription"
    ],
    "realWorldContext": "Call center analytics em pt-BR usa Transcribe Call Analytics + Comprehend para extrair tópicos e sentimento.",
    "commonMistakes": "Misturar Polly (TTS) com Transcribe (STT) — nomes parecidos no início.",
    "tutorSeeds": [
     "Quando usar Transcribe Medical em vez do padrão?",
     "Como melhorar acurácia com vocabulário customizado?"
    ]
   }'::jsonb,
  'AWS AI Services', 'Fundamentals of AI and ML', 'easy', 'scenario', '["transcribe","speech-to-text","ai-services","call-center"]'::jsonb, 'ai-draft', 'active', now(), now()
)
