INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-fund-v1-010', 'aws-aif', 'Em uma rede neural, qual o papel da função de ativação (ReLU, sigmoid, tanh)?',
  '[{"id":"A","text":"Apenas normalizar a entrada da rede"},{"id":"B","text":"Introduzir não-linearidade — sem ela a rede inteira colapsaria em uma combinação linear, independente do número de camadas"},{"id":"C","text":"Reduzir o número de parâmetros da rede"},{"id":"D","text":"Calcular o gradiente do loss"}]'::jsonb, 'B',
  '{
    "summary": "Funções de ativação introduzem não-linearidade — essência do poder das redes profundas.",
    "whyCorrect": "Sem ativações não-lineares, cada camada é apenas uma multiplicação de matrizes (linear). A composição de funções lineares é linear — empilhar 100 camadas lineares equivale a 1 só. As ativações (ReLU, sigmoid, tanh) curvam a função, permitindo que a rede aprenda fronteiras de decisão complexas e não-lineares.",
    "whyWrong": {
     "A": "Normalização é tarefa de BatchNorm/LayerNorm, não da função de ativação.",
     "C": "Funções de ativação não reduzem parâmetros — só transformam ativações. Quem reduz parâmetros é pooling, pruning, dropout.",
     "D": "Gradiente é calculado por backpropagation usando a derivada da ativação — mas o papel da ATIVAÇÃO em si é introduzir não-linearidade."
    },
    "keyConcept": "Funções de ativação — ReLU (padrão), sigmoid (output binário), softmax (multiclasse), tanh",
    "compareWith": [
     "ReLU vs Leaky ReLU vs GELU",
     "Sigmoid (binário) vs Softmax (multiclasse)"
    ],
    "realWorldContext": "ReLU é a ativação default em camadas ocultas de CNN/MLP desde 2012 (AlexNet) — barata e evita vanishing gradient.",
    "commonMistakes": "Usar sigmoid em camadas ocultas profundas — sofre vanishing gradient. ReLU é o padrão hoje.",
    "tutorSeeds": [
     "Por que sigmoid causa vanishing gradient?",
     "Quando GELU supera ReLU?"
    ]
   }'::jsonb,
  'Neural Networks', 'Fundamentals of AI and ML', 'medium', 'recall', '["neural-networks","activation-functions","relu"]'::jsonb, 'ai-draft', 'active', now(), now()
)
