INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-001', 'aws-aif', 'Uma aplicação envia a cada chamada um manual de políticas de 8.000 tokens seguido da pergunta do usuário. O custo mensal está alto. Qual recurso do Bedrock ataca isso diretamente?',
  '[{"id":"A","text":"Prompt caching, marcando o trecho estável para ser reaproveitado entre chamadas"},{"id":"B","text":"Aumentar o maxTokens para reduzir o número de chamadas"},{"id":"C","text":"Trocar para um modelo com janela de contexto maior"},{"id":"D","text":"Ativar streaming da resposta"}]'::jsonb, 'A',
  '{
    "summary": "Prompt caching existe para o caso de prefixo grande e estável repetido em toda chamada.",
    "whyCorrect": "O manual é idêntico a cada requisição, então marcá-lo antes de um ponto de cache faz o Bedrock reaproveitá-lo em vez de reprocessá-lo — é exatamente o padrão que o recurso foi feito para atender, e o guia oficial lista prompt caching como critério de escolha de modelo.",
    "whyWrong": {
     "B": "Aumentar o teto de SAÍDA não reduz o custo de ENTRADA, que é onde estão os 8.000 tokens. Quem escolhe aqui confunde os dois lados da cobrança por token.",
     "C": "Janela maior permite enviar mais contexto e não torna mais barato enviar o mesmo contexto — provavelmente encarece, porque modelos de contexto maior custam mais por token.",
     "D": "Streaming muda QUANDO os tokens chegam ao usuário, melhorando a percepção de latência. O total cobrado é idêntico."
    },
    "keyConcept": "Prompt caching e o modelo de cobrança por token",
    "compareWith": [
     "Custo de entrada vs custo de saída"
    ]
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
