INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-002', 'aws-aif', 'Qual é o papel do Model Context Protocol (MCP) numa arquitetura agêntica?',
  '[{"id":"A","text":"Comprimir o contexto enviado ao modelo para caber na janela"},{"id":"B","text":"Padronizar como um agente descobre e invoca ferramentas de sistemas externos"},{"id":"C","text":"Cifrar a comunicação entre o agente e o modelo"},{"id":"D","text":"Definir a ordem em que múltiplos agentes se comunicam"}]'::jsonb, 'B',
  '{
    "summary": "MCP é protocolo de INTEGRAÇÃO entre agente e ferramenta, e o guia o cita nominalmente.",
    "whyCorrect": "O MCP padroniza a descoberta e a invocação de ferramentas: o servidor descreve o que oferece, o cliente descobre e chama. Isso troca uma integração por par agente-sistema por uma integração por lado.",
    "whyWrong": {
     "A": "Compressão de contexto é engenharia de contexto, outro assunto do mesmo domínio. O nome \"Context\" no protocolo induz a essa troca, e é a pegadinha da questão.",
     "C": "O protocolo não define criptografia; a segurança do transporte vem da camada abaixo, e a autorização é responsabilidade de quem expõe as ferramentas.",
     "D": "Comunicação entre múltiplos agentes é um padrão de arquitetura à parte, também listado no guia, mas distinto de conectar agente a sistema externo."
    },
    "keyConcept": "MCP e conexão de agentes a sistemas externos"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
