INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-003', 'aws-aif', 'Qual conjunto descreve limitações reais de soluções de IA generativa que a prova espera que você reconheça?',
  '[{"id":"A","text":"Impossibilidade de gerar imagem e áudio"},{"id":"B","text":"Necessidade obrigatória de GPU no cliente"},{"id":"C","text":"Alucinação, dificuldade de interpretação, imprecisão e não determinismo"},{"id":"D","text":"Incapacidade de responder em outro idioma"}]'::jsonb, 'C',
  '{
    "summary": "O guia lista quatro desvantagens específicas, e são essas.",
    "whyCorrect": "Alucinação, baixa interpretabilidade, imprecisão e não determinismo são as limitações que o enunciado 2.2 nomeia — e as quatro têm consequência de arquitetura: exigem verificação de saída, registro e tolerância a variação.",
    "whyWrong": {
     "A": "Modelos multimodais e de difusão geram imagem, vídeo e áudio; a alternativa contradiz o próprio catálogo do Bedrock.",
     "B": "Em serviço gerenciado a inferência roda no provedor; GPU no cliente só entra em cenário de execução local, que é outro assunto.",
     "D": "Capacidade multilíngue é justamente um dos critérios de escolha de modelo listados no guia — o oposto de uma limitação universal."
    },
    "keyConcept": "Limitações da GenAI"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
