INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-004', 'aws-aif', 'Uma equipe quer construir um agente em produção com identidade própria, memória entre sessões e observabilidade, sem operar a infraestrutura do laço agêntico. Que serviço a AWS oferece para isso?',
  '[{"id":"A","text":"Amazon SageMaker Canvas"},{"id":"B","text":"AWS Step Functions"},{"id":"C","text":"Amazon Comprehend"},{"id":"D","text":"Amazon Bedrock AgentCore"}]'::jsonb, 'D',
  '{
    "summary": "O guia lista o AgentCore entre os serviços para construir aplicações de GenAI.",
    "whyCorrect": "O AgentCore é o conjunto gerenciado para agentes em produção — identidade, memória, ferramentas e observabilidade —, que é exatamente o que o cenário pede sem operar o laço.",
    "whyWrong": {
     "A": "Canvas é a interface sem código para ML tradicional, voltada a analista de negócio. Não constrói agente nem gerencia sessão.",
     "B": "Step Functions orquestra fluxo de estados definido por você. Serve a um agente, mas não fornece identidade, memória de agente nem o laço agêntico — quem escolhe aqui troca orquestração determinística por agência.",
     "C": "Comprehend faz PLN sobre texto — sentimento, entidade, tópico. É um serviço de tarefa específica, não plataforma de agente."
    },
    "keyConcept": "AgentCore e a plataforma de agentes da AWS"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
