INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-005', 'aws-aif', 'O que é um embedding, e por que ele é a peça central da busca semântica?',
  '[{"id":"A","text":"Uma representação numérica em vetor cuja proximidade reflete semelhança de significado"},{"id":"B","text":"Uma compressão do texto para caber na janela de contexto"},{"id":"C","text":"Um resumo gerado pelo modelo antes de responder"},{"id":"D","text":"Um identificador único do documento no índice"}]'::jsonb, 'A',
  '{
    "summary": "Embedding transforma significado em geometria, e a distância entre vetores passa a medir semelhança.",
    "whyCorrect": "Ao converter texto em vetor, textos com sentido próximo caem em regiões próximas do espaço. Buscar passa a ser encontrar os vizinhos mais próximos do vetor da pergunta, o que funciona mesmo sem palavra em comum.",
    "whyWrong": {
     "B": "Compressão preserva conteúdo para reconstrução; embedding descarta a forma e guarda o significado — não dá para recuperar o texto a partir dele.",
     "C": "Resumo é texto gerado; embedding é vetor numérico. Confundir os dois costuma vir de associar ambos a \"versão menor do documento\".",
     "D": "Identificador é chave arbitrária e não carrega semelhança nenhuma — dois documentos parecidos teriam identificadores completamente diferentes."
    },
    "keyConcept": "Embeddings e busca semântica"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
