INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-006', 'aws-aif', 'Qual métrica de NEGÓCIO é apropriada para avaliar um assistente de atendimento baseado em GenAI?',
  '[{"id":"A","text":"Perplexidade do modelo"},{"id":"B","text":"Taxa de conclusão de tarefa e custo por interação"},{"id":"C","text":"Número de parâmetros"},{"id":"D","text":"Tamanho da janela de contexto"}]'::jsonb, 'B',
  '{
    "summary": "O guia cobra alinhamento entre métrica e objetivo de negócio.",
    "whyCorrect": "Taxa de conclusão de tarefa e custo por interação medem se o assistente resolve o problema do cliente e a que preço — que é o que decide se ele fica no ar.",
    "whyWrong": {
     "A": "Perplexidade é métrica de modelagem de linguagem, útil em pesquisa e ilegível para quem decide orçamento.",
     "C": "Número de parâmetros é característica do modelo e não diz nada sobre resultado. É a alternativa que confunde tamanho com valor.",
     "D": "Janela de contexto é capacidade técnica; ela habilita casos de uso e não mede nenhum deles."
    },
    "keyConcept": "Métricas de negócio para aplicações de GenAI"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
