INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-007', 'aws-aif', 'Por que a estratégia de chunking afeta diretamente a qualidade de um sistema de RAG?',
  '[{"id":"A","text":"Porque o tamanho do fragmento define o custo de armazenamento no S3"},{"id":"B","text":"Porque o chunking define a temperatura da geração"},{"id":"C","text":"Porque o fragmento é a unidade recuperada: pequeno demais perde contexto, grande demais dilui o sinal e traz ruído"},{"id":"D","text":"Porque fragmentos maiores sempre melhoram a resposta"}]'::jsonb, 'C',
  '{
    "summary": "O fragmento é a unidade de recuperação, então ele determina o que chega ao modelo.",
    "whyCorrect": "Um fragmento curto pode cortar a informação no meio e perder o contexto que a tornava útil; um fragmento longo mistura vários assuntos, e o vetor resultante representa mal cada um deles. A escolha é um equilíbrio, e é por isso que existe chunking fixo, hierárquico e semântico.",
    "whyWrong": {
     "A": "O custo de armazenamento é irrelevante nessa ordem de grandeza, e não é o que muda a qualidade da resposta.",
     "B": "Temperatura é parâmetro de inferência, definido na chamada e sem relação com como o acervo foi fatiado.",
     "D": "\"Maior é sempre melhor\" é a intuição que a questão desmonta: o fragmento grande dilui o sinal e ainda consome mais tokens de entrada."
    },
    "keyConcept": "Chunking e qualidade de RAG"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
