INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-008', 'aws-aif', 'Uma carga tem volume previsível e constante, e a equipe quer capacidade garantida e custo estável para inferência no Bedrock. Qual opção atende?',
  '[{"id":"A","text":"Throughput sob demanda"},{"id":"B","text":"Inferência em lote"},{"id":"C","text":"Perfil de inferência entre regiões"},{"id":"D","text":"Throughput provisionado"}]'::jsonb, 'D',
  '{
    "summary": "O guia cobra os trade-offs de custo dos serviços de GenAI, incluindo throughput provisionado.",
    "whyCorrect": "Throughput provisionado reserva capacidade por um compromisso de tempo, entregando vazão garantida e custo previsível — o desenho certo quando o volume é constante e a variação de latência é inaceitável.",
    "whyWrong": {
     "A": "Sob demanda cobra por token e não garante capacidade em pico: você compete por cota compartilhada, que é justamente o que o cenário quer evitar.",
     "B": "Lote reduz custo para trabalho assíncrono e não serve a uma carga que exige resposta contínua.",
     "C": "Perfil entre regiões melhora disponibilidade distribuindo a chamada por geografia; ajuda contra limitação de taxa, mas não reserva capacidade nem estabiliza o custo."
    },
    "keyConcept": "Throughput provisionado vs sob demanda"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
