INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-009', 'aws-aif', 'O que é engenharia de contexto, e como ela difere de engenharia de prompt?',
  '[{"id":"A","text":"Prompt trata da instrução; contexto trata de QUE informação entra na janela, em que ordem e com que orçamento de tokens"},{"id":"B","text":"São o mesmo assunto com nomes diferentes"},{"id":"C","text":"Engenharia de contexto é o ajuste fino do modelo"},{"id":"D","text":"Engenharia de contexto significa aumentar a janela do modelo"}]'::jsonb, 'A',
  '{
    "summary": "O guia lista engenharia de contexto como assunto próprio no enunciado 2.1.",
    "whyCorrect": "Engenharia de prompt cuida de como pedir; engenharia de contexto cuida do que colocar na janela — seleção do que é relevante, ordem que preserva a atenção e orçamento de tokens por parte.",
    "whyWrong": {
     "B": "Tratar como sinônimo faz perder a decisão mais cara em aplicação de RAG e de agente: o que NÃO entrar na janela.",
     "C": "Ajuste fino altera os pesos do modelo; engenharia de contexto não toca no modelo, só no que se envia a ele.",
     "D": "Aumentar a janela é escolher outro modelo. Encher uma janela grande de conteúdo irrelevante piora a resposta e o custo — é o oposto da prática."
    },
    "keyConcept": "Engenharia de contexto vs engenharia de prompt"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
