INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-010', 'aws-aif', 'Um gestor pergunta por que o mesmo prompt devolveu respostas diferentes em duas execuções. Qual é a explicação correta?',
  '[{"id":"A","text":"O modelo foi retreinado entre as chamadas"},{"id":"B","text":"Geração é não determinística por natureza; parâmetros de amostragem como temperature controlam o grau de variação"},{"id":"C","text":"Houve falha de rede que corrompeu a resposta"},{"id":"D","text":"O serviço alternou automaticamente para outro modelo"}]'::jsonb, 'B',
  '{
    "summary": "Não determinismo é característica declarada da GenAI, não defeito.",
    "whyCorrect": "A geração amostra o próximo token de uma distribuição de probabilidade. Com temperature acima de zero, execuções idênticas produzem saídas diferentes — e reduzir a temperature aproxima do determinismo sem garanti-lo plenamente.",
    "whyWrong": {
     "A": "Modelos gerenciados não são retreinados entre duas chamadas suas; versões novas chegam como identificadores novos, sob seu controle.",
     "C": "Falha de rede produz erro, tempo esgotado ou resposta truncada — nunca duas respostas completas, válidas e diferentes. Atribuir variação legítima a defeito de infraestrutura leva a caçar problema onde não há.",
     "D": "A troca de modelo é explícita no `modelId`. Supor troca automática é atribuir ao serviço um comportamento que tornaria qualquer avaliação impossível."
    },
    "keyConcept": "Não determinismo e parâmetros de amostragem"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
