INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-011', 'aws-aif', 'Qual é a principal vantagem de usar um serviço gerenciado de GenAI em vez de hospedar o próprio modelo?',
  '[{"id":"A","text":"O modelo gerenciado sempre tem qualidade superior"},{"id":"B","text":"Elimina completamente a preocupação com segurança de dados"},{"id":"C","text":"Barreira de entrada menor: sem provisionar GPU, sem operar escala e sem aplicar patch, com custo por uso"},{"id":"D","text":"Remove a necessidade de avaliar o modelo"}]'::jsonb, 'C',
  '{
    "summary": "O guia lista acessibilidade, barreira de entrada, eficiência e velocidade até o mercado como vantagens.",
    "whyCorrect": "O serviço gerenciado tira do seu prato a infraestrutura de inferência — capacidade, escala, atualização — e converte investimento inicial em custo por uso, encurtando o caminho até a primeira versão em produção.",
    "whyWrong": {
     "A": "Qualidade depende do modelo escolhido, não do modo de hospedagem; o mesmo modelo pode ser servido dos dois jeitos.",
     "B": "Segurança é responsabilidade COMPARTILHADA: o provedor cuida da infraestrutura, e o controle de acesso, a proteção do dado e o filtro de saída continuam sendo seus.",
     "D": "Avaliação continua obrigatória — e fica mais importante, porque trocar de modelo passa a ser barato e frequente."
    },
    "keyConcept": "Vantagens de serviço gerenciado de GenAI"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
