INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-012', 'aws-aif', 'Uma equipe precisa que um agente lembre de preferências do usuário entre sessões distintas. Que conceito agêntico endereça isso?',
  '[{"id":"A","text":"Uso de ferramentas"},{"id":"B","text":"Orquestração de fluxo"},{"id":"C","text":"Comunicação entre múltiplos agentes"},{"id":"D","text":"Gerenciamento de memória"}]'::jsonb, 'D',
  '{
    "summary": "O guia lista gerenciamento de memória entre os conceitos fundamentais de IA agêntica.",
    "whyCorrect": "Memória é o mecanismo que persiste informação além do contexto de uma sessão, permitindo que o agente reconheça preferências e histórico em interações futuras.",
    "whyWrong": {
     "A": "Uso de ferramentas é como o agente age sobre sistemas externos; ele poderia gravar em um banco por ferramenta, mas o CONCEITO que a pergunta nomeia é memória.",
     "B": "Orquestração define a ordem dos passos dentro de uma execução, e o problema aqui atravessa execuções.",
     "C": "Comunicação entre agentes trata de vários agentes cooperando na mesma tarefa, não de persistência ao longo do tempo."
    },
    "keyConcept": "Memória em sistemas agênticos"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
