INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-013', 'aws-aif', 'Qual fator NÃO deveria pesar na escolha entre dois foundation models para um caso de uso regulado?',
  '[{"id":"A","text":"Popularidade do modelo nas redes sociais"},{"id":"B","text":"Latência exigida pela aplicação"},{"id":"C","text":"Conformidade e onde o dado é processado"},{"id":"D","text":"Custo por token no volume esperado"}]'::jsonb, 'A',
  '{
    "summary": "A questão testa se você separa critério técnico e de negócio de ruído.",
    "whyCorrect": "Popularidade não é critério: ela não diz nada sobre latência, custo, conformidade nem adequação à tarefa, que são os eixos que o guia lista.",
    "whyWrong": {
     "B": "Latência é critério explícito de seleção no enunciado 3.1 e frequentemente decide entre um modelo grande e um menor.",
     "C": "Conformidade e local de processamento são decisivos em setor regulado — em muitos casos eliminam opções antes de qualquer teste de qualidade.",
     "D": "Custo por token no volume esperado é o que transforma uma escolha viável em inviável na escala real."
    },
    "keyConcept": "Critérios de seleção de foundation model"
   }'::jsonb,
