INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-014', 'aws-aif', 'Uma startup quer prototipar rapidamente com modelos abertos, com notebooks e modelos pré-treinados prontos para ajuste. Qual recurso da AWS é o caminho mais direto?',
  '[{"id":"A","text":"Amazon Bedrock Guardrails"},{"id":"B","text":"SageMaker JumpStart"},{"id":"C","text":"AWS Glue DataBrew"},{"id":"D","text":"Amazon Kendra"}]'::jsonb, 'B',
  '{
    "summary": "JumpStart é o catálogo de modelos e soluções prontos do SageMaker.",
    "whyCorrect": "JumpStart entrega modelos pré-treinados e exemplos de ajuste com poucos cliques, que é o caminho mais curto para prototipar com modelos abertos.",
    "whyWrong": {
     "A": "Guardrails é controle de segurança sobre entrada e saída de modelo; não fornece modelo nem ambiente de prototipagem.",
     "C": "DataBrew é preparação visual de dados — etapa anterior no ciclo e de outro assunto. Quem escolhe aqui associa \"prototipar rápido\" a \"ferramenta visual\", ignorando que o pedido é por MODELO pronto, não por tratamento de dado.",
     "D": "Kendra é busca empresarial e pode alimentar a recuperação de um RAG, mas não fornece modelo pré-treinado nem ambiente de ajuste — é a peça de retrieval, não a de modelagem."
    },
    "keyConcept": "SageMaker JumpStart"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
