INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-015', 'aws-aif', 'Como o modelo de cobrança por token afeta a decisão de arquitetura de um assistente com histórico longo de conversa?',
  '[{"id":"A","text":"Não afeta: o custo é fixo por chamada"},{"id":"B","text":"O custo depende apenas do tamanho da resposta"},{"id":"C","text":"Cada volta reenvia o histórico, então o custo de entrada cresce com o tamanho da conversa — o que torna resumo e teto de voltas decisões de arquitetura"},{"id":"D","text":"O histórico é armazenado pelo serviço e cobrado uma vez"}]'::jsonb, 'C',
  '{
    "summary": "A API não guarda estado: continuidade é responsabilidade da aplicação, e ela é paga em tokens de entrada.",
    "whyCorrect": "Como todo o histórico é reenviado a cada volta, o custo acumulado cresce muito mais rápido que o número de mensagens. Resumir o histórico antigo e limitar o número de voltas deixam de ser detalhe e viram decisão de desenho.",
    "whyWrong": {
     "A": "A cobrança é por token, não por chamada — é o ponto central do enunciado 2.1 sobre preço. Quem marca aqui costuma raciocinar por analogia com API REST tradicional, onde o custo é por requisição e independe do tamanho do corpo.",
     "B": "A saída é cobrada, e em conversa longa a ENTRADA costuma dominar, justamente por causa do reenvio do histórico.",
     "D": "O serviço não mantém a conversa entre chamadas; supor isso leva a subestimar o custo e a implementar continuidade que não existe."
    },
    "keyConcept": "Cobrança por token e histórico de conversa"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
