INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-fundamentals-v4-016', 'aws-aif', 'Em qual cenário a IA generativa é a escolha ERRADA?',
  '[{"id":"A","text":"Resumir chamados de suporte"},{"id":"B","text":"Gerar variações de texto publicitário"},{"id":"C","text":"Responder perguntas sobre uma base de documentos internos"},{"id":"D","text":"Calcular o valor exato de imposto devido segundo tabela legal"}]'::jsonb, 'D',
  '{
    "summary": "Onde se exige resultado exato e auditável, cálculo determinístico vence geração.",
    "whyCorrect": "O imposto é definido por tabela e regra; a resposta precisa ser exata e reproduzível. Um modelo generativo produz texto plausível, e plausível não é o mesmo que correto num cálculo legal.",
    "whyWrong": {
     "A": "Resumo é caso de uso listado no guia e tolera variação de forma, desde que o conteúdo esteja correto.",
     "B": "Gerar variações é o caso em que a natureza não determinística vira VANTAGEM: você quer saídas diferentes a cada execução. Descartar por causa da variação é aplicar ao caso criativo o critério do caso exato.",
     "C": "Perguntas sobre base interna é o caso canônico de RAG, com a ressalva de exigir ancoragem na fonte."
    },
    "keyConcept": "Quando GenAI não é apropriada"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
