INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-001', 'aws-aif', 'Uma equipe precisa que um chatbot responda perguntas sobre 50.000 documentos internos da empresa, atualizados diariamente. As respostas devem citar fontes específicas. Qual abordagem é a mais adequada?',
  '[{"id":"A","text":"RAG: indexar documentos em vector store, recuperar trechos relevantes e passar como contexto ao FM"},{"id":"B","text":"Fine-tuning de um foundation model com os 50.000 documentos como dataset de treino"},{"id":"C","text":"Context stuffing: enviar todos os 50.000 documentos no prompt a cada pergunta"},{"id":"D","text":"Pre-training from scratch de um modelo proprietário com os documentos"}]'::jsonb, 'A',
  '{
    "summary": "RAG é a escolha padrão quando há grande volume de docs dinâmicos + necessidade de citação de fontes.",
    "whyCorrect": "RAG (Retrieval-Augmented Generation) recupera apenas os trechos relevantes via similaridade vetorial e injeta no contexto. Atualização diária = re-indexar (segundos/minutos), sem re-treinamento. Citações = você sabe exatamente quais chunks foram usados.",
    "whyWrong": {
     "B": "Fine-tuning ensina padrão/estilo, não fatos atualizáveis. Para 50k docs mudando diariamente seria caro, lento e impossível citar fontes — o modelo ''misturaria'' o conhecimento.",
     "C": "Context stuffing estoura o context window de qualquer FM atual e custa $$$ por chamada — mesmo modelos de 1M tokens não comportam 50k documentos inteiros.",
     "D": "Pre-training from scratch custa milhões de dólares e meses de compute — completamente desproporcional ao problema."
    },
    "keyConcept": "RAG vs Fine-tuning vs Context stuffing — escolha pela natureza dos dados (dinâmicos/grandes/citáveis)",
    "compareWith": [
     "RAG vs Fine-tuning",
     "Vector retrieval vs full-context"
    ],
    "realWorldContext": "Caso de uso #1 de empresas em 2025: chatbot de Q&A sobre base de conhecimento corporativa (Confluence, SharePoint, S3).",
    "commonMistakes": "Achar que fine-tuning ''ensina os documentos'' — fine-tuning ensina padrão de resposta, não fatos verificáveis.",
    "tutorSeeds": [
     "Quando combinar RAG + fine-tuning?",
     "Como medir qualidade de retrieval no RAG?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["rag","fine-tuning","vector-store","knowledge-base"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
