  status        = 'active',
  updated_at    = now();

INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-002', 'aws-aif', 'Uma fintech quer que o LLM responda sempre em formato JSON estruturado com campos específicos (account_id, risk_score, recommendation), em um estilo consistente para 100k chamadas/dia. Prompt engineering com few-shot ainda gera ~3% de respostas mal-formadas. Qual técnica resolve melhor o problema de FORMATO/ESTILO consistente?',
  '[{"id":"A","text":"RAG com mais exemplos no vector store"},{"id":"B","text":"Fine-tuning supervisionado com 1.000 exemplos do formato desejado"},{"id":"C","text":"Aumentar temperature para 0.9 para mais criatividade"},{"id":"D","text":"Usar modelo maior (de Sonnet para Opus)"}]'::jsonb, 'B',
  '{
    "summary": "Fine-tuning é a ferramenta certa quando o problema é PADRÃO/ESTILO, não conhecimento.",
    "whyCorrect": "Fine-tuning supervisionado com pares (input, output_json_desejado) ensina o modelo a SEMPRE produzir o formato. Reduz drasticamente a taxa de saídas mal-formadas (de 3% para <0.1%), economiza tokens (prompt mais curto sem few-shots) e reduz latência.",
    "whyWrong": {
     "A": "RAG resolve falta de conhecimento, não falta de consistência de formato. Mais exemplos no vector store não ensinam estilo.",
     "C": "Temperature alta PIORA consistência — você quer determinismo aqui (temperature 0 ou bem baixa).",
     "D": "Modelo maior pode reduzir um pouco erros mas é solução cara e indireta — fine-tuning com 1k exemplos é dramaticamente mais eficaz para formato."
    },
    "keyConcept": "Fine-tuning para padrão/estilo/formato; RAG para conhecimento dinâmico",
    "compareWith": [
     "Fine-tuning para estilo vs few-shot prompting",
     "Constrained decoding vs fine-tuning"
    ],
    "realWorldContext": "Sistemas de underwriting, classificação automática, extração estruturada de PDFs — todos beneficiam de fine-tuning leve.",
    "commonMistakes": "Achar que fine-tuning serve para ''ensinar fatos novos'' — para fatos, use RAG.",
    "tutorSeeds": [
     "Quantos exemplos de fine-tuning são suficientes?",
     "Constrained decoding pode substituir fine-tuning?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["fine-tuning","format-consistency","json-output"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
