INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-003', 'aws-aif', 'Um time precisa traduzir um documento técnico de 80 páginas (≈40k tokens) preservando contexto entre seções. Cada chamada à API custa por token. Qual estratégia é a mais eficiente em CUSTO sem sacrificar coerência?',
  '[{"id":"A","text":"Mandar o documento inteiro em uma única chamada num modelo de context window grande (200k+)"},{"id":"B","text":"Quebrar em chunks de 1k tokens e traduzir cada um independentemente em paralelo"},{"id":"C","text":"Chunks de 4k tokens com janela de overlap de 200 tokens + manter glossário de termos consistentes entre chamadas"},{"id":"D","text":"Fine-tune um modelo para tradução específica antes de processar o documento"}]'::jsonb, 'C',
  '{
    "summary": "Chunking com overlap + glossário = trade ótimo entre custo, latência e coerência.",
    "whyCorrect": "Chunks de 4k são processados rapidamente, overlap de 200 tokens preserva contexto nas fronteiras, glossário compartilhado entre chamadas mantém termos técnicos consistentes (ex: ''eventual consistency'' sempre traduzido igual). Custo total ≈ 1x do documento + ~5% overhead por overlap.",
    "whyWrong": {
     "A": "Pode funcionar mas: (1) modelos com 200k+ context são mais caros por token, (2) latência alta (geração lenta em prompts grandes), (3) qualidade pode degradar em prompts muito longos (''lost in the middle'').",
     "B": "Chunks de 1k sem overlap quebram contexto nas fronteiras e geram traduções inconsistentes — frases cortadas no meio, termos traduzidos diferente em cada chunk.",
     "D": "Fine-tuning de 1 documento é overkill — custo do treino > custo da tradução. Só faz sentido para volume contínuo."
    },
    "keyConcept": "Chunking strategy — chunk size, overlap, shared state (glossário)",
    "compareWith": [
     "Long-context model vs chunking",
     "Overlap vs no-overlap chunking"
    ],
    "realWorldContext": "Tradução de livros, contratos jurídicos, manuais técnicos — sempre chunking com glossário.",
    "commonMistakes": "Achar que ''context window grande resolve tudo'' — modelos grandes degradam qualidade em prompts muito longos (lost-in-the-middle).",
    "tutorSeeds": [
     "Como medir ''lost in the middle'' em LLMs?",
     "Quando map-reduce summarization supera single-call?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["chunking","cost-optimization","long-context"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
