INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-004', 'aws-aif', 'Uma equipe construiu um sistema que: (1) recebe pergunta do usuário, (2) decide se precisa consultar a API de clima, a calculadora ou nenhum tool, (3) executa a tool escolhida, (4) reflete sobre o resultado, (5) pode executar OUTRA tool, (6) gera resposta final. Esse padrão é melhor descrito como?',
  '[{"id":"A","text":"Single LLM call com prompt elaborado"},{"id":"B","text":"RAG simples"},{"id":"C","text":"Fine-tuning supervised"},{"id":"D","text":"Agent (multi-step com tools e reasoning)"}]'::jsonb, 'D',
  '{
    "summary": "Decidir/executar/refletir/repetir = padrão de Agent (ReAct, Tool Use).",
    "whyCorrect": "Agents combinam reasoning + tool use + multi-step. O loop ''pensar → escolher tool → executar → observar → continuar'' é a definição de agent (ReAct paper, Bedrock Agents, LangChain Agents).",
    "whyWrong": {
     "A": "Single call não permite reflexão após resultado de tool — uma chamada termina depois de gerar texto.",
     "B": "RAG só recupera contexto antes da geração — não escolhe tools dinamicamente nem reflete.",
     "C": "Fine-tuning ensina padrão estatístico, não orquestra chamadas a APIs externas em runtime."
    },
    "keyConcept": "Agent loop — Plan → Act → Observe → Reflect → repeat",
    "compareWith": [
     "Agent multi-step vs single LLM call",
     "ReAct vs Plan-and-Execute"
    ],
    "realWorldContext": "Assistente que reserva voos consultando calendar + sistema de pagamento + airline API.",
    "commonMistakes": "Confundir ''function calling em 1 turno'' com ''agent'' — agent é o LOOP, não a tool em si.",
    "tutorSeeds": [
     "Qual a diferença entre ReAct e Reflexion?",
     "Como evitar loops infinitos em agents?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'easy', 'recall', '["agent","react","tool-use"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
