INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-005', 'aws-aif', 'Para um caso de uso ''gerar título de e-mail a partir do corpo'' (volume: 10M chamadas/dia, latência alvo p95 < 500ms, qualidade aceitável), qual escolha de modelo é mais adequada considerando o TRADE-OFF cost/latency/quality?',
  '[{"id":"A","text":"Modelo S (Claude Haiku / GPT-4o-mini) — tarefa simples, alto volume, latência crítica"},{"id":"B","text":"Modelo XL (Claude Opus / GPT-4) por máxima qualidade"},{"id":"C","text":"Modelo M (Claude Sonnet / GPT-4o) como padrão seguro"},{"id":"D","text":"Pre-train custom model"}]'::jsonb, 'A',
  '{
    "summary": "Tarefa simples + alto volume + latência crítica = modelo pequeno/rápido (small/fast tier).",
    "whyCorrect": "Gerar título é tarefa LEVE (1-2 frases, baixa complexidade de reasoning). Modelo S oferece: latência 5-10x menor que XL, custo 50-100x menor, qualidade suficiente. Em 10M chamadas/dia a diferença de custo é dramática (centenas de milhares de USD/mês).",
    "whyWrong": {
     "B": "XL desperdiça poder computacional em tarefa trivial, viola SLA de latência (Opus tem p95 ~2-5s) e custa proibitivamente em 10M req/dia.",
     "C": "Sonnet é razoável mas ainda é mais caro/lento que Haiku para uma tarefa que Haiku resolve com qualidade equivalente.",
     "D": "Pre-train custom só faz sentido com terabytes de dados específicos e budget de milhões — completamente desproporcional."
    },
    "keyConcept": "FM size selection matrix — cost × latency × quality vs task complexity × volume",
    "compareWith": [
     "Haiku vs Sonnet vs Opus tradeoff",
     "Routing simples para modelo S, complexo para XL"
    ],
    "realWorldContext": "Padrão: Haiku/Mini para classificação/sumarização curta, Sonnet/4o para Q&A/análise, Opus/o1 para reasoning profundo.",
    "commonMistakes": "Usar ''modelo melhor'' em tudo por default — quase sempre é overengineering caro.",
    "tutorSeeds": [
     "Como implementar model routing por complexidade do prompt?",
     "Quando upgrade de Haiku para Sonnet vale a pena?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["model-selection","cost-latency-quality","tradeoff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
