INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-006', 'aws-aif', 'Sua aplicação faz 5M chamadas/mês ao Bedrock. Você observa que 30% das perguntas são EXATAMENTE iguais (FAQ comuns) e 20% são semanticamente similares (mesma intenção, palavras diferentes). Quais camadas de cache implementar?',
  '[{"id":"A","text":"Apenas response cache (chave = hash do prompt exato)"},{"id":"B","text":"Response cache (hash exato) + semantic cache (embedding similarity \u003e 0.95)"},{"id":"C","text":"Apenas KV cache no GPU do provider"},{"id":"D","text":"Não usar cache — sempre chamar o modelo para garantir freshness"}]'::jsonb, 'B',
  '{
    "summary": "Combinar response cache (exact match) + semantic cache (embedding) cobre tanto repetição exata quanto paráfrases.",
    "whyCorrect": "Response cache resolve os 30% exatos com lookup O(1) (Redis/DynamoDB). Semantic cache calcula embedding da query e busca no vector store por similaridade > limiar; cobre os 20% similares. Resultado: 50% das chamadas servidas sem invocar LLM — economia massiva.",
    "whyWrong": {
     "A": "Cobre só 30%, deixa 20% de paráfrases na mesa.",
     "C": "KV cache é otimização INTERNA do provider (reuso de prefixos no GPU) — você não controla diretamente em managed services e ele só ajuda em prompts com prefixo compartilhado.",
     "D": "Pagar 5M chamadas quando 50% poderiam vir do cache é desperdício enorme. Para FAQs, freshness não muda a cada segundo."
    },
    "keyConcept": "Camadas de cache para LLM: exact-match (response) + semantic (embedding) + prompt prefix (KV/prompt cache)",
    "compareWith": [
     "Response cache vs semantic cache",
     "Exact match vs fuzzy matching"
    ],
    "realWorldContext": "Chatbots de atendimento têm 40-70% de cache hit com semantic cache bem ajustado.",
    "commonMistakes": "Cache sem TTL gera staleness — sempre ter política de invalidação por evento ou tempo.",
    "tutorSeeds": [
     "Como escolher threshold de similarity para semantic cache?",
     "Quando NÃO cachear (compliance, personalização)?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'best-practice', '["caching","semantic-cache","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
