INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-007', 'aws-aif', 'Você quer monitorar a SAÚDE OPERACIONAL de uma aplicação LLM em produção. Quais métricas são as MAIS importantes para alertas e dashboards?',
  '[{"id":"A","text":"Apenas total de chamadas/dia"},{"id":"B","text":"Apenas a acurácia em um dataset de validação offline"},{"id":"C","text":"Latency p50/p95/p99, token throughput (in/out), cost per call, error rate por tipo de erro"},{"id":"D","text":"Tamanho do modelo em bilhões de parâmetros"}]'::jsonb, 'C',
  '{
    "summary": "Operação de LLM requer telemetria multi-dimensão: performance (p50/p95/p99), throughput, custo e erros.",
    "whyCorrect": "Latency percentis revelam outliers (p99 alto = clientes específicos sofrendo); token throughput separa tokens IN (custo) de OUT (latência); cost/call atrela observability ao FinOps; error rate por tipo (rate limit, content filter, timeout, 5xx) direciona ação corretiva.",
    "whyWrong": {
     "A": "Total/dia não revela degradação dentro do dia, não distingue erros, não direciona ação.",
     "B": "Acurácia offline é importante mas não monitora SAÚDE OPERACIONAL — não detecta um spike de latência às 14h.",
     "D": "Tamanho do modelo é configuração, não métrica operacional."
    },
    "keyConcept": "LLM observability stack — latency percentis, throughput, cost, error rate, success rate",
    "compareWith": [
     "Operational metrics vs quality metrics",
     "p50 vs p95 vs p99"
    ],
    "realWorldContext": "Datadog/Honeycomb/CloudWatch dashboards de produção LLM sempre têm essas 4 camadas.",
    "commonMistakes": "Olhar só avg latency — esconde a cauda longa que afeta UX.",
    "tutorSeeds": [
     "Por que p99 importa mais que avg em LLM?",
     "Como atribuir cost por tenant em multi-tenant LLM apps?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'best-practice', '["monitoring","observability","p95-p99","cost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
