INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-008', 'aws-aif', 'Após 2 semanas em produção, a qualidade percebida das respostas do seu LLM caiu — usuários reclamam de respostas ''fora do tópico''. As métricas de latência e erro estão normais. O modelo NÃO foi alterado. Qual fenômeno é o mais provável?',
  '[{"id":"A","text":"Bug no SDK"},{"id":"B","text":"Falha de hardware no provider"},{"id":"C","text":"Cache poisoning"},{"id":"D","text":"Drift na distribuição de inputs (usuários começaram a fazer perguntas diferentes do esperado)"}]'::jsonb, 'D',
  '{
    "summary": "Métricas operacionais OK + qualidade caindo = drift de inputs (input drift / concept drift).",
    "whyCorrect": "Quando latência/erros estão normais mas qualidade percebida cai, geralmente a DISTRIBUIÇÃO de inputs mudou. Ex: usuários começaram a perguntar sobre tema fora do escopo do prompt/RAG. Detecção: tracking de embeddings dos inputs em janelas temporais, alerta quando KL-divergence cresce.",
    "whyWrong": {
     "A": "Bug de SDK costuma gerar erros/timeouts — não ''respostas fora do tópico''.",
     "B": "Falha de hardware aparece em error rate / latency p99.",
     "C": "Cache poisoning é hipótese válida mas rara e específica — drift de inputs é muito mais comum em prod."
    },
    "keyConcept": "Input drift / concept drift detection em LLM apps",
    "compareWith": [
     "Input drift vs model degradation",
     "Embedding-based drift detection"
    ],
    "realWorldContext": "Bot de suporte que entrou em produção em janeiro começa a receber dúvidas sobre nova feature lançada em março — drift de inputs.",
    "commonMistakes": "Culpar o modelo quando a entrada é que mudou — sempre monitorar a distribuição de inputs.",
    "tutorSeeds": [
     "Como medir drift via embeddings?",
     "Diferença entre data drift e concept drift?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'troubleshoot', '["drift-detection","monitoring","quality-degradation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
