INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-009', 'aws-aif', 'Sua aplicação chama a API Bedrock e em horários de pico recebe HTTP 429 (Throttling). Você quer maior disponibilidade SEM travar o usuário. Qual estratégia de FAILOVER é a melhor?',
  '[{"id":"A","text":"Exponential backoff com jitter + failover para modelo secundário (mesmo provider, modelo equivalente, ou cross-region inference)"},{"id":"B","text":"Retry imediato no mesmo modelo até sucesso"},{"id":"C","text":"Aumentar Provisioned Throughput para 10x do necessário"},{"id":"D","text":"Ignorar erros 429 e deixar o usuário tentar novamente"}]'::jsonb, 'A',
  '{
    "summary": "Backoff + failover multi-modelo/multi-region é o padrão para resiliência LLM.",
    "whyCorrect": "Exponential backoff com jitter evita thundering herd, e failover para modelo secundário (ex: Sonnet → Haiku, ou region us-east-1 → us-west-2 via cross-region inference) mantém SLA quando o primário satura.",
    "whyWrong": {
     "B": "Retry imediato sem backoff piora throttling — você bombardeia o serviço já saturado.",
     "C": "Provisioned Throughput 10x é caro (paga mesmo sem uso) e ainda assim não protege contra falha regional.",
     "D": "Deixar erro vazar para o usuário é péssima UX e desperdiça oportunidade de retry."
    },
    "keyConcept": "Resilience patterns — exponential backoff, jitter, failover, cross-region inference",
    "compareWith": [
     "Retry com backoff vs Circuit breaker",
     "Cross-region inference vs Provisioned Throughput"
    ],
    "realWorldContext": "Bedrock cross-region inference profiles foram criados exatamente para esse caso.",
    "commonMistakes": "Retry sem jitter cria sincronização de retries (todos os clientes batem no mesmo segundo).",
    "tutorSeeds": [
     "Como configurar cross-region inference no Bedrock?",
     "Quando usar Provisioned Throughput vs On-demand?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["rate-limit","failover","resilience","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
