INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-010', 'aws-aif', 'Você quer mudar o prompt do seu chatbot em produção, mas tem receio de regredir qualidade. Qual abordagem de deploy minimiza risco?',
  '[{"id":"A","text":"Substituir o prompt em produção e monitorar feedback"},{"id":"B","text":"Canary deploy: 5% do tráfego no prompt novo, comparar métricas de qualidade vs controle, expandir gradualmente"},{"id":"C","text":"Manter prompts em variáveis hardcoded no código"},{"id":"D","text":"Editar diretamente o prompt template em S3 sem versionar"}]'::jsonb, 'B',
  '{
    "summary": "Canary deploy é o padrão seguro para mudanças de prompt em produção.",
    "whyCorrect": "Canary com 5%/25%/50%/100% permite comparar métricas (acceptance rate, thumbs up/down, conversion) entre prompt novo vs controle em tráfego real. Rollback é instantâneo se métricas degradarem.",
    "whyWrong": {
     "A": "Big-bang sem canary — 100% dos usuários expostos à regressão até você notar.",
     "C": "Hardcoded impede mudança rápida sem novo deploy de código + sem versionamento auditável.",
     "D": "Sem versionamento você não consegue rollback nem A/B test — prompts são código, merecem versionamento."
    },
    "keyConcept": "Prompt versioning + canary deploy + A/B test = LLMOps maturity",
    "compareWith": [
     "Canary vs Blue/Green deploy",
     "A/B test vs canary"
    ],
    "realWorldContext": "Bedrock Prompt Management, LangSmith, PromptLayer — todos têm versionamento de prompt nativo.",
    "commonMistakes": "Tratar prompt como string aleatória em código — prompt é artefato versionável.",
    "tutorSeeds": [
     "Como medir ''qualidade de prompt'' em produção?",
     "Bedrock Prompt Management vs solução in-house?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'best-practice', '["prompt-versioning","canary-deploy","llmops"]'::jsonb, 'ai-draft', 'active', now(), now()
)
