INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-011', 'aws-aif', 'Você precisa montar um EVALUATION HARNESS automático para seu chatbot RAG. Quais componentes são essenciais?',
  '[{"id":"A","text":"Apenas um set de perguntas e respostas esperadas com BLEU score"},{"id":"B","text":"Apenas o feedback thumbs up/down dos usuários"},{"id":"C","text":"Dataset de perguntas representativas + ground-truth + métricas (faithfulness, answer relevance, context precision/recall) + LLM-as-judge + tracking ao longo do tempo"},{"id":"D","text":"Apenas perplexity do modelo"}]'::jsonb, 'C',
  '{
    "summary": "Eval harness moderno para RAG precisa de dataset + métricas específicas + LLM-as-judge + temporal tracking.",
    "whyCorrect": "Sistema robusto: (1) Dataset curado representativo do uso real; (2) Ground-truth (respostas esperadas e/ou trechos relevantes); (3) Métricas específicas de RAG (faithfulness = resposta fiel ao contexto; answer relevance = resposta responde a pergunta; context precision/recall = retrieval acertou); (4) LLM-as-judge para escalar avaliação subjetiva; (5) Run periódico para detectar regressão.",
    "whyWrong": {
     "A": "BLEU é métrica de tradução, péssima para Q&A aberta — penaliza paráfrases corretas.",
     "B": "Thumbs UP/DOWN é importante mas é signal, não eval harness — não substitui dataset offline reproduzível.",
     "D": "Perplexity mede fluência do modelo, não qualidade de resposta no caso de uso."
    },
    "keyConcept": "RAG eval framework — Ragas, TruLens, LlamaIndex evaluators, LLM-as-judge",
    "compareWith": [
     "BLEU/ROUGE vs LLM-as-judge",
     "Offline eval vs online metrics"
    ],
    "realWorldContext": "Ragas é o framework open-source mais popular para eval de RAG (faithfulness, context_precision, answer_relevancy).",
    "commonMistakes": "Confiar só em métricas tradicionais de NLP (BLEU/ROUGE) — não capturam corretude factual.",
    "tutorSeeds": [
     "Como usar LLM-as-judge sem bias?",
     "Frameworks para eval de RAG?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'best-practice', '["evaluation","rag-eval","llm-as-judge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
