INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-012', 'aws-aif', 'Você quer detectar HALLUCINATIONS em tempo de execução, não só em eval offline. Qual técnica é a mais escalável e prática para integrar ao runtime?',
  '[{"id":"A","text":"Pedir para 3 humanos revisarem cada resposta"},{"id":"B","text":"Aumentar temperature do modelo"},{"id":"C","text":"Trocar para modelo maior em todas as chamadas"},{"id":"D","text":"Calcular groundedness score: similaridade entre claims da resposta e trechos retornados pelo retriever (RAG); abaixo de threshold → flag/regenerar/escalar"}]'::jsonb, 'D',
  '{
    "summary": "Groundedness/faithfulness scoring em runtime detecta hallucinations sem revisão humana de cada chamada.",
    "whyCorrect": "Para apps RAG, decompor resposta em claims atômicos e checar cada um contra os trechos recuperados (via NLI ou LLM-as-judge) dá score 0-1. Se score < threshold → regenerar com prompt mais restritivo, ou escalar para humano, ou recusar resposta. Escalável e automático.",
    "whyWrong": {
     "A": "Revisão humana de cada chamada é impossível em produção (custo, latência, escala).",
     "B": "Temperature alta AUMENTA hallucinations — quer-se o oposto.",
     "C": "Modelos maiores reduzem hallucinations marginalmente, mas não eliminam — e custam mais. Groundedness check funciona com qualquer modelo."
    },
    "keyConcept": "Runtime hallucination detection — groundedness, faithfulness, NLI-based check",
    "compareWith": [
     "Groundedness vs answer relevance",
     "NLI vs LLM-as-judge para check"
    ],
    "realWorldContext": "Bedrock Guardrails tem ContextualGroundingCheck nativo — checa groundedness em runtime.",
    "commonMistakes": "Achar que ''modelo grande não alucina'' — todos alucinam, só varia a taxa.",
    "tutorSeeds": [
     "Como Bedrock Guardrails detecta hallucinations?",
     "NLI models para verificação factual?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["hallucination","groundedness","runtime-check","guardrails"]'::jsonb, 'ai-draft', 'active', now(), now()
)
