INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-013', 'aws-aif', 'Para fine-tunar um modelo com pares (entrada, saída) você só tem 200 exemplos rotulados manualmente. Quer expandir para 5.000. Qual técnica é a mais escalável?',
  '[{"id":"A","text":"Synthetic data generation: usar um LLM mais forte para gerar variações + validar amostralmente"},{"id":"B","text":"Contratar 50 anotadores humanos para rotular mais 4.800 exemplos"},{"id":"C","text":"Repetir os 200 exemplos 25 vezes para chegar a 5.000"},{"id":"D","text":"Não treinar — usar só os 200 com few-shot prompting"}]'::jsonb, 'A',
  '{
    "summary": "Synthetic data generation com LLM teacher + validação amostral é a abordagem escalável padrão.",
    "whyCorrect": "Usar um modelo MAIS FORTE (ex: Opus) como ''teacher'' para gerar variações dos 200 seed examples expande dataset para milhares. Validação amostral por humanos (5-10%) detecta erros sistemáticos. Padrão usado no Self-Instruct, Alpaca, e em fine-tuning corporativo.",
    "whyWrong": {
     "B": "Caro, lento, e desnecessário se LLM puder gerar com qualidade suficiente.",
     "C": "Duplicação não adiciona informação — modelo memoriza em vez de generalizar (overfitting).",
     "D": "Few-shot é alternativa válida, mas a pergunta é COMO expandir para 5k — synthetic generation responde isso."
    },
    "keyConcept": "Synthetic data generation — LLM as teacher, Self-Instruct, data augmentation",
    "compareWith": [
     "Synthetic vs human-labeled",
     "Distillation vs synthetic generation"
    ],
    "realWorldContext": "Alpaca, Vicuna, e muitos open-source LLMs foram treinados com synthetic data de GPT-4 como teacher.",
    "commonMistakes": "Não validar synthetic data — pode introduzir bias do teacher e propagar erros.",
    "tutorSeeds": [
     "Como evitar bias do teacher em synthetic data?",
     "Self-Instruct vs Evol-Instruct?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["synthetic-data","fine-tuning","data-augmentation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
