INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-014', 'aws-aif', 'Você precisa processar um PDF que contém texto, tabelas, gráficos e diagramas (ex: relatório financeiro). Qual modalidade de modelo escolher?',
  '[{"id":"A","text":"Modelo text-only após OCR — pipeline tradicional"},{"id":"B","text":"Modelo multimodal (vision+text) que aceita imagens das páginas diretamente"},{"id":"C","text":"Modelo de áudio porque processa sequências"},{"id":"D","text":"Modelo de embedding sem geração"}]'::jsonb, 'B',
  '{
    "summary": "PDFs com diagramas/tabelas/gráficos = use modelo multimodal (vision+text) ao invés de OCR + text-only.",
    "whyCorrect": "Modelos multimodais (Claude 3+/4, GPT-4o, Nova) interpretam layout, gráficos, tabelas e diagramas diretamente — preservando estrutura visual que OCR perde. Para relatórios financeiros, capturar layout de tabela é crítico.",
    "whyWrong": {
     "A": "OCR puro perde estrutura (tabelas viram texto plano corrompido), não interpreta gráficos, falha em diagramas. Pipeline frágil.",
     "C": "Modelo de áudio é para fala, não para imagens/texto.",
     "D": "Embedding sem geração não responde perguntas sobre o documento."
    },
    "keyConcept": "Multimodal model choice — quando vision+text supera OCR + text-only",
    "compareWith": [
     "OCR + LLM vs Vision LLM end-to-end",
     "Multimodal vs text-only"
    ],
    "realWorldContext": "Análise de notas fiscais, contratos com cláusulas em layout específico, relatórios anuais.",
    "commonMistakes": "Insistir em OCR clássico para docs com layout rico — perde precisão e adiciona steps frágeis.",
    "tutorSeeds": [
     "Quando OCR ainda é melhor que vision LLM?",
     "Custo de tokens em modelos multimodais?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'easy', 'best-practice', '["multimodal","vision","document-processing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
