INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-015', 'aws-aif', 'Sua aplicação LLM precisa ser auditada por compliance. Eles pedem ''reproducibility'' — que a MESMA chamada gere a MESMA resposta. Qual configuração você adota?',
  '[{"id":"A","text":"temperature=1.0, top_p=1.0"},{"id":"B","text":"Sempre o modelo XL para maior consistência"},{"id":"C","text":"temperature=0, seed fixo se suportado, logar prompt + parâmetros + model version + timestamp + response"},{"id":"D","text":"Cachear todas as respostas indefinidamente"}]'::jsonb, 'C',
  '{
    "summary": "Reprodutibilidade aproximada = temperature 0 + seed + logging completo (audit trail).",
    "whyCorrect": "Temperature 0 (greedy decoding) minimiza variância na escolha de tokens. Seed fixo (quando disponível) elimina restos não-determinísticos. Logar prompt+params+model version+timestamp+response cria audit trail completo — mesmo se modelo evoluir, você prova o que aconteceu.",
    "whyWrong": {
     "A": "Temperature 1.0 maximiza randomness — pior cenário para reprodutibilidade.",
     "B": "Tamanho não garante determinismo; configuração de sampling sim.",
     "D": "Cache imutável é workaround, não solução real — não responde a inputs novos."
    },
    "keyConcept": "Reproducibility em LLMs — temperature, seed, model versioning, audit logging",
    "compareWith": [
     "Greedy decoding vs sampling",
     "Audit trail completo vs parcial"
    ],
    "realWorldContext": "Setores regulados (saúde, financeiro, governo) exigem audit trail completo de cada chamada LLM.",
    "commonMistakes": "Achar que temperature 0 = determinismo total — ainda há non-determinism em GPU floating-point, batching, etc.",
    "tutorSeeds": [
     "Por que temperature 0 não é 100% determinístico?",
     "Como armazenar audit trail compliant com LGPD?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["reproducibility","compliance","audit","temperature"]'::jsonb, 'ai-draft', 'active', now(), now()
)
