INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-016', 'aws-aif', 'Em qual cenário FINE-TUNING é MAIS apropriado do que RAG?',
  '[{"id":"A","text":"Você precisa que o modelo responda sobre 10.000 documentos jurídicos atualizados toda semana"},{"id":"B","text":"Você precisa citar a fonte exata de cada resposta"},{"id":"C","text":"Você precisa que o modelo conheça eventos que aconteceram após o cutoff de treino"},{"id":"D","text":"Você quer que o modelo adote o ESTILO/TOM específico da sua marca em todas as respostas, com vocabulário próprio"}]'::jsonb, 'D',
  '{
    "summary": "Fine-tuning brilha em estilo/tom/padrão consistente; RAG brilha em fatos dinâmicos e citáveis.",
    "whyCorrect": "Estilo de marca, tom, vocabulário próprio, persona — esses são padrões aprendidos via fine-tuning supervisionado. RAG não muda ''como'' o modelo escreve; muda ''sobre o que'' ele tem acesso.",
    "whyWrong": {
     "A": "10k docs dinâmicos = RAG (atualizar índice é fácil; re-treinar é caro/lento).",
     "B": "Citar fonte = RAG (você sabe quais chunks foram retornados; fine-tuning ''mistura'' conhecimento).",
     "C": "Fatos pós-cutoff = RAG (basta indexar dados novos)."
    },
    "keyConcept": "Quando escolher Fine-tuning: padrão/estilo/formato/tarefa; quando RAG: conhecimento dinâmico/citável",
    "compareWith": [
     "Fine-tuning vs RAG",
     "Estilo vs Conhecimento"
    ],
    "realWorldContext": "Empresas com voz de marca forte (Apple, Nike) usam fine-tuning para chatbots; empresas com base de conhecimento (Confluence) usam RAG.",
    "commonMistakes": "Misturar ''eu quero o modelo saber X'' (use RAG) com ''eu quero o modelo escrever como X'' (use FT).",
    "tutorSeeds": [
     "RAG + fine-tuning combinados — quando?",
     "PEFT (LoRA) vs full fine-tuning?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["fine-tuning","rag","tradeoff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
