INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-017', 'aws-aif', 'Você tem 3 versões de prompt (v1 controle, v2 mais estruturado, v3 com persona). Quer escolher a melhor antes de promover. Qual técnica é mais robusta?',
  '[{"id":"A","text":"A/B/C test com tráfego dividido + métricas pré-definidas (acceptance, conversion, thumbs-up) + significância estatística"},{"id":"B","text":"Comparar manualmente 5 saídas de cada prompt"},{"id":"C","text":"Pedir para o LLM decidir qual prompt é melhor"},{"id":"D","text":"Escolher o prompt mais longo por princípio"}]'::jsonb, 'A',
  '{
    "summary": "A/B/C test estatístico em produção é o gold standard para selecionar entre versões de prompt.",
    "whyCorrect": "Tráfego dividido (ex: 33%/33%/34%) com métricas pré-definidas e teste de significância (p-value ou Bayesian) permite decisão objetiva baseada em comportamento real do usuário, não em intuição.",
    "whyWrong": {
     "B": "5 saídas é amostra minúscula, sujeita a viés de seleção.",
     "C": "LLM-as-judge tem bias e não captura sinal de comportamento real do usuário.",
     "D": "Mais longo ≠ melhor — geralmente prompts curtos e específicos vencem."
    },
    "keyConcept": "A/B testing de prompts em produção — controle vs tratamento, significância",
    "compareWith": [
     "A/B test online vs eval offline",
     "p-value vs Bayesian decision"
    ],
    "realWorldContext": "PromptLayer, LangSmith, Statsig, Optimizely — todos suportam A/B test de prompts.",
    "commonMistakes": "Declarar vencedor com 10 amostras — sem significância estatística é teatro.",
    "tutorSeeds": [
     "Como calcular tamanho amostral mínimo para A/B test de prompt?",
     "Multi-armed bandit vs A/B clássico para prompts?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'best-practice', '["a-b-test","prompt-versioning","significance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
