INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-018', 'aws-aif', 'Sua app LLM tem múltiplos passos: classificar intent → recuperar contexto → gerar resposta → validar. Cada step usa LLM. Qual antipattern você deve EVITAR?',
  '[{"id":"A","text":"Logar input/output de cada step para tracing"},{"id":"B","text":"Usar modelo XL em todos os 4 steps por consistência"},{"id":"C","text":"Usar modelo S/M nos steps simples (classificação, validação) e modelo M/L só na geração principal"},{"id":"D","text":"Implementar circuit breaker entre steps"}]'::jsonb, 'B',
  '{
    "summary": "Usar modelo grande em todos os steps quando steps simples podem rodar em modelo pequeno é desperdício 10-100x.",
    "whyCorrect": "Classificação de intent (1 classe entre 10) e validação de formato JSON são tarefas TRIVIAIS para modelos S/Haiku. Usar Opus em todos os 4 steps multiplica custo e latência sem ganho real de qualidade. Padrão correto: modelo S para steps simples, M/L para steps complexos.",
    "whyWrong": {
     "A": "Logging de cada step é boa prática (tracing distribuído de chains/agents).",
     "C": "Esse é justamente o padrão correto — model routing por complexidade.",
     "D": "Circuit breaker é boa prática (impede cascata de falhas)."
    },
    "keyConcept": "Model routing in multi-step pipelines — small model para steps simples, large para complexos",
    "compareWith": [
     "Uniform model choice vs routed model choice",
     "Cost per pipeline run"
    ],
    "realWorldContext": "LangChain LCEL, LlamaIndex, Bedrock Flows — todos permitem trocar modelo por step.",
    "commonMistakes": "Usar ''modelo top'' por default em todos os componentes — custa 10x mais sem ganho.",
    "tutorSeeds": [
     "Como medir ''complexidade'' de step para rotear modelo?",
     "Custo total de pipeline com modelos heterogêneos?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["model-routing","pipeline","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
