INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-019', 'aws-aif', 'Você quer construir uma camada de SAFETY antes e depois do LLM. Qual arquitetura é a mais robusta?',
  '[{"id":"A","text":"Apenas confiar no alinhamento do modelo base"},{"id":"B","text":"Aumentar temperature para o modelo ser mais ''criativo''"},{"id":"C","text":"Prompt firewall (input filtering: PII, prompt injection, topic out-of-scope) + LLM call + Output validation (toxicity, PII leak, schema check, hallucination) + Escalation path para humano em casos críticos"},{"id":"D","text":"Não validar saídas porque o modelo é confiável"}]'::jsonb, 'C',
  '{
    "summary": "Safety em LLM é defesa em camadas: input filter + LLM + output filter + escalation.",
    "whyCorrect": "Input firewall (Bedrock Guardrails, Lakera, Llama Guard) bloqueia PII, injection, topic OOS antes de gastar tokens. LLM gera. Output validation re-checa toxicidade, PII leak, schema e groundedness. Casos com baixa confiança ou alto risco → escalação para humano. Cada camada falha graciosamente.",
    "whyWrong": {
     "A": "Alinhamento sozinho falha contra adversários (jailbreaks, injection); precisa de defesa em profundidade.",
     "B": "Temperature alta não tem nada a ver com safety — só aumenta variância.",
     "D": "Confiança cega no modelo gera incidents de PII leak, conteúdo tóxico, etc."
    },
    "keyConcept": "Defense in depth para LLM apps — input firewall + output validation + human escalation",
    "compareWith": [
     "Bedrock Guardrails vs Llama Guard vs Lakera",
     "Pre-call vs Post-call filtering"
    ],
    "realWorldContext": "Toda app LLM em produção em setor regulado tem essas camadas (banco, saúde, gov).",
    "commonMistakes": "Tratar safety como ''só prompt engineering'' — não escala e é frágil.",
    "tutorSeeds": [
     "Como Bedrock Guardrails diferencia de Llama Guard?",
     "O que é prompt injection e como mitigar?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'best-practice', '["safety","guardrails","prompt-injection","defense-in-depth"]'::jsonb, 'ai-draft', 'active', now(), now()
)
