INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-021', 'aws-aif', 'Em qual cenário um AGENT multi-step com tools é JUSTIFICÁVEL ao invés de single LLM call?',
  '[{"id":"A","text":"Reservar um voo: consultar disponibilidade na API da cia + verificar limite no cartão do usuário + confirmar reserva + enviar email — com decisões intermediárias"},{"id":"B","text":"Traduzir uma frase de inglês para português"},{"id":"C","text":"Sumarizar um artigo de 500 palavras"},{"id":"D","text":"Corrigir ortografia de um parágrafo"}]'::jsonb, 'A',
  '{
    "summary": "Agent justifica overhead quando há múltiplas APIs externas + decisões condicionais + estado entre steps.",
    "whyCorrect": "Reservar voo envolve 4 tools externas em sequência com decisões (se cartão sem limite, parar; se disponibilidade indisponível, propor data alternativa). Agent é a abstração correta — gerencia loop, estado, tool selection.",
    "whyWrong": {
     "B": "Tradução é single call — nenhum tool, nenhum reasoning multi-step.",
     "C": "Sumarização é single call — pega texto, gera summary.",
     "D": "Correção ortográfica é single call ou até regex/spellchecker tradicional."
    },
    "keyConcept": "Quando usar Agent: multi-tool, multi-step, decisions, state — NÃO para tarefas single-shot",
    "compareWith": [
     "Agent vs chain vs single call",
     "Tools deterministic vs LLM-decided"
    ],
    "realWorldContext": "Bedrock Agents foi desenhado exatamente para casos como reserva de hotel, processo de fulfillment, orquestração de APIs.",
    "commonMistakes": "Usar agent em tudo (overengineering) — agents trazem latência, custo e debug complexo.",
    "tutorSeeds": [
     "Quando agent supera workflow estático?",
     "Custo de agent vs single call?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["agent","tool-use","tradeoff","multi-step"]'::jsonb, 'ai-draft', 'active', now(), now()
)
