INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-022', 'aws-aif', 'Um time relata: ''p50 latency está 1.2s mas p99 está 18s''. Isso é problema? Por quê?',
  '[{"id":"A","text":"Não é problema — a média deve estar baixa"},{"id":"B","text":"É problema sério: 1 em 100 usuários sofre experiência horrível, possíveis timeouts em UI, signal de cauda longa que pode crescer"},{"id":"C","text":"Não é problema — latência alta é normal em LLM"},{"id":"D","text":"Resolver aumentando timeout do cliente para 60s"}]'::jsonb, 'B',
  '{
    "summary": "Gap grande entre p50 e p99 = tail latency problem, afeta UX e indica problemas estruturais.",
    "whyCorrect": "Em escala (1M req/dia), p99 = 18s afeta 10k requests/dia com péssima UX. Tail latency em LLM tem causas estruturais: prompts mais longos, throttling intermitente, cold start, contention de GPU no provider. Atacá-la requer: streaming, cap em max_tokens, request timeout, retry com modelo menor.",
    "whyWrong": {
     "A": "Avg/p50 esconde a cauda. Métricas centrais não bastam.",
     "C": "Latência alta no p99 não é ''normal'' — é sintoma a investigar.",
     "D": "Aumentar timeout maquia o problema, não resolve — usuário ainda espera."
    },
    "keyConcept": "Tail latency em LLM — p50 vs p95 vs p99, causas estruturais, mitigações",
    "compareWith": [
     "Avg vs p50 vs p99",
     "Streaming vs full response"
    ],
    "realWorldContext": "Streaming reduz time-to-first-token (perceived latency) mesmo se total time não muda.",
    "commonMistakes": "Olhar só avg ou p50 — ''parece OK'' enquanto 1% sofre.",
    "tutorSeeds": [
     "Como reduzir p99 em apps LLM?",
     "Streaming reduz latência real ou só percebida?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'troubleshoot', '["latency","p99","tail-latency","monitoring"]'::jsonb, 'ai-draft', 'active', now(), now()
)
