INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-023', 'aws-aif', 'Você está escolhendo entre 3 estratégias: (a) RAG, (b) fine-tuning com 5k exemplos, (c) context stuffing manual em cada prompt. Para ''responder dúvidas sobre os 200 produtos do catálogo da empresa, catálogo cresce 10 produtos/mês'', qual é a melhor?',
  '[{"id":"A","text":"(b) Fine-tuning"},{"id":"B","text":"(c) Context stuffing dos 200 produtos no prompt"},{"id":"C","text":"(a) RAG"},{"id":"D","text":"Nenhuma — usar modelo pre-trained sem contexto"}]'::jsonb, 'C',
  '{
    "summary": "Catálogo dinâmico (cresce mensalmente) com fontes citáveis = RAG é a escolha canônica.",
    "whyCorrect": "RAG: indexar 200 produtos (re-index quando novos chegam, em minutos). Recupera só os 3-5 produtos relevantes por pergunta. Custo de token baixo, atualização trivial, citação de fonte.",
    "whyWrong": {
     "A": "Fine-tuning fica desatualizado a cada lançamento — você teria que re-treinar mensalmente, caro e lento.",
     "B": "Context stuffing dos 200 produtos a cada chamada custa muitos tokens em prompts repetitivos. Funciona mas é ineficiente.",
     "D": "Modelo pre-trained não conhece seu catálogo proprietário."
    },
    "keyConcept": "RAG é a default quando: catálogo grande/dinâmico/citável; context stuffing só se catálogo é pequeno e estático",
    "compareWith": [
     "RAG vs context stuffing — break-even point",
     "Custo de re-train vs re-index"
    ],
    "realWorldContext": "Chatbots de e-commerce com milhares de SKUs em rotação usam RAG (Bedrock Knowledge Base + OpenSearch).",
    "commonMistakes": "Stuffing tudo no prompt ''porque o context window cabe'' — gasta token e perde ''lost in the middle''.",
    "tutorSeeds": [
     "Bedrock Knowledge Base — como funciona internamente?",
     "Vector store: Pinecone vs OpenSearch vs pgvector?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["rag","tradeoff","catalog"]'::jsonb, 'ai-draft', 'active', now(), now()
)
