INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-024', 'aws-aif', 'Sobre KV CACHE (prompt cache) em LLMs — qual afirmação é CORRETA?',
  '[{"id":"A","text":"KV cache substitui a necessidade de vector store"},{"id":"B","text":"KV cache só funciona com fine-tuning"},{"id":"C","text":"KV cache é o mesmo que semantic cache"},{"id":"D","text":"KV cache acelera respostas reutilizando o cálculo de atenção para o PREFIXO compartilhado entre chamadas"}]'::jsonb, 'D',
  '{
    "summary": "KV cache reutiliza cache de atenção de tokens de PREFIXO comum entre chamadas, reduzindo TTFT e custo.",
    "whyCorrect": "Em transformers, cada token de entrada gera key/value vectors. Se 90% do prompt é igual (system prompt + few-shots fixos), o provider pode cachear esses K/V e só processar a parte nova. Reduz custo (Bedrock/Anthropic/OpenAI cobram menos por tokens cacheados) e time-to-first-token.",
    "whyWrong": {
     "A": "Vector store é para retrieval (RAG); KV cache é para reuso de cálculo do transformer — coisas diferentes.",
     "B": "KV cache funciona em qualquer modelo, fine-tuned ou não.",
     "C": "Semantic cache armazena RESPOSTAS prontas por similaridade; KV cache reutiliza CÁLCULO INTERMEDIÁRIO do prefixo do prompt — camadas distintas."
    },
    "keyConcept": "KV cache (prompt caching) — reuso de cálculo de attention para tokens de prefixo comum",
    "compareWith": [
     "KV cache vs semantic cache vs response cache",
     "Prompt caching Anthropic vs OpenAI"
    ],
    "realWorldContext": "Anthropic prompt caching cobra ~10% dos tokens cacheados; OpenAI tem prompt caching automático.",
    "commonMistakes": "Confundir KV cache (reuso de cálculo) com semantic cache (reuso de resposta).",
    "tutorSeeds": [
     "Como estruturar prompts para maximizar prompt caching?",
     "Custo de write cache vs read cache (Anthropic)?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["kv-cache","prompt-caching","latency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
