INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-025', 'aws-aif', 'Para um problema de classificação binária (spam/ham) com 100M chamadas/mês, qual abordagem MAXIMIZA cost-efficiency mantendo qualidade aceitável?',
  '[{"id":"A","text":"Fine-tunar um modelo pequeno (ex: Haiku ou Nova Micro) com dataset de spam — uma vez treinado, inferência é barata e rápida"},{"id":"B","text":"Chamar Claude Opus para cada email"},{"id":"C","text":"RAG com base de emails históricos"},{"id":"D","text":"Agent multi-step para cada email"}]'::jsonb, 'A',
  '{
    "summary": "Classificação binária de alto volume = fine-tune modelo pequeno e barato; classificadores tradicionais (BERT) também viáveis.",
    "whyCorrect": "Fine-tune de Haiku/Nova Micro com 50k exemplos rotulados gera classificador eficiente: latência ms, custo baixíssimo por chamada. Em 100M/mês, qualquer chamada cara é proibitiva. Alternativa: fine-tune BERT/DistilBERT (sem API LLM).",
    "whyWrong": {
     "B": "Opus em 100M chamadas/mês geraria custo de centenas de milhares de dólares. Overkill para binary classification.",
     "C": "RAG não agrega valor para classificação que aprende padrão estatístico.",
     "D": "Agent multi-step para classificação binária é overengineering absurdo."
    },
    "keyConcept": "Para tarefas DISCRIMINATIVAS de alto volume, escolha modelo pequeno fine-tuned (ou BERT-like) — não LLM generativo grande",
    "compareWith": [
     "Generative LLM vs Discriminative classifier (BERT)",
     "Fine-tune small vs API large"
    ],
    "realWorldContext": "Filtros de spam de Gmail/Outlook usam classificadores especializados, não LLMs generativos.",
    "commonMistakes": "Usar GPT-4/Opus para classificação binária — você paga 1000x mais sem ganhar qualidade real.",
    "tutorSeeds": [
     "Quando BERT supera LLM generativo?",
     "Modelo pequeno fine-tuned vs LLM com prompt — custo/qualidade?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["fine-tuning","classification","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
