INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-026', 'aws-aif', 'Sua equipe quer fazer BENCHMARK do seu modelo em MMLU e outros datasets públicos. Qual risco é importante mitigar?',
  '[{"id":"A","text":"O benchmark vai usar muita energia"},{"id":"B","text":"BENCHMARK CONTAMINATION — o modelo pode ter visto os dados de teste durante o treino, inflando os scores"},{"id":"C","text":"Benchmarks são lentos"},{"id":"D","text":"Não há risco em benchmarks públicos"}]'::jsonb, 'B',
  '{
    "summary": "Benchmarks públicos podem ter sido vistos pelo modelo no pre-training (data leak) — scores ficam inflados.",
    "whyCorrect": "MMLU, HumanEval, GSM8K já vazaram em corpora de pre-training de muitos modelos. Resultado: modelo pode reproduzir respostas memorizadas. Mitigações: testes em datasets PRIVADOS, datasets recentes (pós-cutoff), análise de canários inseridos.",
    "whyWrong": {
     "A": "Energia é preocupação real mas não é o risco metodológico principal.",
     "C": "Lentidão é operacional, não invalida resultados.",
     "D": "Há sim risco metodológico sério em benchmarks públicos."
    },
    "keyConcept": "Benchmark contamination — data leakage entre pre-training e datasets de eval",
    "compareWith": [
     "Public benchmark vs private eval set",
     "Memorization vs generalization"
    ],
    "realWorldContext": "Lab de pesquisa sério sempre tem ''held-out'' privado para evitar contaminação.",
    "commonMistakes": "Confiar 100% em scores de MMLU — leaderboards estão saturados por contaminação.",
    "tutorSeeds": [
     "Como detectar contamination empiricamente?",
     "Por que GSM8K-Hard foi criado?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["benchmark","contamination","evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
