INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-027', 'aws-aif', 'Qual ciclo descreve corretamente o DATA LIFECYCLE de uma aplicação LLM em produção, do início ao fim?',
  '[{"id":"A","text":"Treinar → Deploy"},{"id":"B","text":"Apenas chamar o modelo"},{"id":"C","text":"Collect (logs/feedback) → Filter (PII, quality, dedup) → Train/Fine-tune → Eval (benchmark + production metrics) → Deploy → Monitor → Collect (loop)"},{"id":"D","text":"Comprar dataset pronto e treinar"}]'::jsonb, 'C',
  '{
    "summary": "Data lifecycle LLM é cíclico: coleta de dados de uso → filtragem → treino/fine-tune → eval → deploy → monitora → coleta novamente.",
    "whyCorrect": "Padrão MLOps/LLMOps maduro: dados de produção (com consentimento) viram inputs para futura iteração; filtros removem PII e baixa qualidade; eval garante não-regressão; monitoring fecha o loop com drift detection.",
    "whyWrong": {
     "A": "Falta filtragem, eval, monitor, e o LOOP — descreve um projeto morto.",
     "B": "Não é lifecycle, é apenas inferência.",
     "D": "Comprar dataset é apenas o início — falta todo o ciclo."
    },
    "keyConcept": "LLMOps data lifecycle — collect, filter, train, eval, deploy, monitor, iterate",
    "compareWith": [
     "MLOps vs LLMOps lifecycle",
     "Continuous learning vs batch retraining"
    ],
    "realWorldContext": "Empresas com LLM em produção que iteram modelo: Anthropic, OpenAI, Google fazem ciclos contínuos.",
    "commonMistakes": "Tratar LLM como deploy ''once and done'' — sem ciclo, qualidade degrada.",
    "tutorSeeds": [
     "Como filtrar PII em logs antes de re-treinar?",
     "Active learning em LLM?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'best-practice', '["data-lifecycle","llmops","iteration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
