INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-028', 'aws-aif', 'Você quer ''graceful degradation'' quando o modelo primário (Sonnet) falha. Qual é o padrão correto?',
  '[{"id":"A","text":"Mostrar mensagem ''serviço indisponível'' ao usuário"},{"id":"B","text":"Retry no Sonnet infinitamente"},{"id":"C","text":"Crashar o servidor"},{"id":"D","text":"Fallback chain: Sonnet → Haiku → resposta pré-computada/template → mensagem clara ao usuário se TODOS falharem"}]'::jsonb, 'D',
  '{
    "summary": "Graceful degradation = cadeia de fallbacks de qualidade decrescente, terminando em mensagem amigável.",
    "whyCorrect": "Cadeia: modelo principal → modelo backup mais barato/disponível → resposta cacheada/template estática → mensagem clara. Cada degrau preserva experiência razoável; falha total é último recurso.",
    "whyWrong": {
     "A": "Pular direto para erro perde oportunidades de servir o usuário com qualidade reduzida.",
     "B": "Retry infinito amplifica throttling.",
     "C": "Crash de servidor é a antítese de graceful degradation."
    },
    "keyConcept": "Graceful degradation — multi-tier fallback chain",
    "compareWith": [
     "Fallback chain vs single failover",
     "Static fallback vs cached fallback"
    ],
    "realWorldContext": "Apps maduras de LLM têm 3-4 níveis de fallback (Sonnet → Haiku → cache → static).",
    "commonMistakes": "Só ter 1 nível de fallback — quando ambos falham, usuário recebe erro cru.",
    "tutorSeeds": [
     "Como cachear fallback responses eficientemente?",
     "Circuit breaker + fallback chain combinados?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["failover","graceful-degradation","resilience"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
