INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-029', 'aws-aif', 'Você deseja medir CUSTO POR USUÁRIO num app multi-tenant LLM. Como atribuir corretamente?',
  '[{"id":"A","text":"Logar tokens IN/OUT por chamada com tag de tenant + multiplicar pelo preço do modelo + agregar por usuário/período"},{"id":"B","text":"Dividir custo total pelo número de usuários"},{"id":"C","text":"Cobrar todos igualmente"},{"id":"D","text":"Ignorar — custo é overhead da empresa"}]'::jsonb, 'A',
  '{
    "summary": "FinOps de LLM exige atribuição granular: tokens × preço × tenant tag = custo verdadeiro por usuário.",
    "whyCorrect": "Tagging por tenant em cada chamada + tracking de tokens IN/OUT (preços diferentes) + tabela de pricing do modelo permite calcular custo real por usuário. Base para alocação interna ou pricing externo (usage-based).",
    "whyWrong": {
     "B": "Média esconde heavy users — alguns consomem 100x mais que outros.",
     "C": "Pricing flat injusto e financeiramente arriscado (heavy users derrubam margem).",
     "D": "Custos de LLM podem ser dezenas de milhares/mês — ignorar é financeiramente irresponsável."
    },
    "keyConcept": "LLM FinOps — token-level cost attribution per tenant",
    "compareWith": [
     "Flat pricing vs usage-based pricing",
     "Average cost vs per-tenant cost"
    ],
    "realWorldContext": "Plataformas SaaS com LLM têm dashboards de cost-per-customer e usage caps por plano.",
    "commonMistakes": "Não taggear chamadas por tenant — depois é impossível reconstruir custo histórico.",
    "tutorSeeds": [
     "Bedrock cost allocation tags — como configurar?",
     "Quando passar custo de LLM para o cliente?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'best-practice', '["cost-attribution","finops","multi-tenant"]'::jsonb, 'ai-draft', 'active', now(), now()
)
