INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-030', 'aws-aif', 'Para escolher entre RAG e LONG-CONTEXT WINDOW (ex: passar 500k tokens direto ao modelo), qual fator é mais decisivo?',
  '[{"id":"A","text":"Cor da interface"},{"id":"B","text":"Frequência de mudança dos dados + custo por chamada + necessidade de citar fontes + ''lost in the middle''"},{"id":"C","text":"Linguagem de programação usada"},{"id":"D","text":"Cor do logo da empresa"}]'::jsonb, 'B',
  '{
    "summary": "RAG vs long-context decide-se por: dinamismo dos dados, custo de tokens IN, citação, e qualidade em contextos longos.",
    "whyCorrect": "RAG vence quando dados mudam frequentemente (re-index é barato), volume é grande (custo de IN tokens em long-context fica alto), citação é necessária (você sabe quais chunks foram retornados), e ''lost in the middle'' afeta long-context (qualidade degrada em prompts muito longos).",
    "whyWrong": {
     "A": "Irrelevante.",
     "C": "Irrelevante para a decisão arquitetural.",
     "D": "Irrelevante."
    },
    "keyConcept": "RAG vs Long-context — fatores de decisão técnico-econômicos",
    "compareWith": [
     "RAG vs Long-context",
     "Lost-in-the-middle effect"
    ],
    "realWorldContext": "Mesmo com Gemini 2M context, RAG continua dominante em produção por custo e citação.",
    "commonMistakes": "Achar que ''context window grande resolve tudo'' — custo e qualidade no longo prazo dizem outra coisa.",
    "tutorSeeds": [
     "Quando long-context vence RAG?",
     "Híbrido RAG + long-context — quando combinar?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'easy', 'scenario', '["rag","long-context","tradeoff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
