INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-031', 'aws-aif', 'Como detectar METRIC DRIFT (mudança gradual em métricas como acceptance rate) em produção LLM?',
  '[{"id":"A","text":"Olhar uma vez por mês"},{"id":"B","text":"Esperar usuários reclamarem"},{"id":"C","text":"Time series de métricas com baseline rolling (ex: 7d) + alertas estatísticos (z-score \u003e 3 ou CUSUM) + análise causal por cohort"},{"id":"D","text":"Reiniciar o servidor"}]'::jsonb, 'C',
  '{
    "summary": "Drift detection automatizado = baseline rolling + signal estatístico + análise causal.",
    "whyCorrect": "Time series com janela móvel detecta tendência; teste estatístico (z-score, CUSUM, KS test) dispara alerta quando desvio é significativo; análise por cohort (por feature, por tenant, por modelo) ajuda a isolar causa raiz.",
    "whyWrong": {
     "A": "Mensal é tarde demais — drifts podem acumular dano semanal.",
     "B": "Reativo, com dano à reputação já causado.",
     "D": "Restart não tem relação com drift de qualidade."
    },
    "keyConcept": "Metric drift detection — rolling baseline, statistical signals, cohort analysis",
    "compareWith": [
     "Drift por input vs por output",
     "Z-score vs CUSUM"
    ],
    "realWorldContext": "SageMaker Model Monitor e ferramentas como Arize, WhyLabs fazem isso automaticamente.",
    "commonMistakes": "Olhar apenas avg agregada — esconde drift em segmentos específicos.",
    "tutorSeeds": [
     "Como configurar SageMaker Model Monitor?",
     "CUSUM vs EWMA para drift detection?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'best-practice', '["drift","monitoring","metrics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
