INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-032', 'aws-aif', 'Você está aplicando RATE LIMITING na sua API LLM para proteger custos. Qual algoritmo permite picos curtos sem prejudicar UX?',
  '[{"id":"A","text":"Hard cap fixo de N req/s — recusa imediata acima disso"},{"id":"B","text":"Bloquear todos os usuários após 100 req/min globais"},{"id":"C","text":"Random drop de 50% das requests"},{"id":"D","text":"Token bucket: enche em rate fixo, permite burst até a capacidade do bucket"}]'::jsonb, 'D',
  '{
    "summary": "Token bucket permite bursts naturais respeitando rate médio — ideal para UX humana.",
    "whyCorrect": "Token bucket: cada request consome 1 token; bucket enche a rate constante; tamanho do bucket permite bursts. Combina proteção (rate longo prazo) com bom UX (curtos picos absorvidos).",
    "whyWrong": {
     "A": "Hard cap rejeita usuários legítimos em picos curtos.",
     "B": "Limite global pune usuários individuais por carga de outros.",
     "C": "Random drop é arbitrário e confunde o cliente."
    },
    "keyConcept": "Rate limiting algorithms — token bucket vs leaky bucket vs sliding window",
    "compareWith": [
     "Token bucket vs Leaky bucket",
     "Per-user vs global rate limit"
    ],
    "realWorldContext": "API Gateway, Cloudflare, e maioria das LLM APIs usam token bucket por padrão.",
    "commonMistakes": "Confundir token bucket de rate limiting com ''tokens'' de LLM — homonímia confusa.",
    "tutorSeeds": [
     "Como configurar rate limit no API Gateway?",
     "Per-tenant vs per-IP rate limit?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["rate-limit","token-bucket","api"]'::jsonb, 'ai-draft', 'active', now(), now()
)
