INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-033', 'aws-aif', 'Sua app LLM atende usuários em PT-BR, mas o modelo foi treinado majoritariamente em inglês. Você nota qualidade inferior em PT-BR. Quais opções enderem o problema?',
  '[{"id":"A","text":"Mix de: (1) escolher modelo com forte suporte multilíngue (Nova, Claude); (2) fine-tune com corpus PT-BR; (3) prompt em português com exemplos PT-BR; (4) testar em dataset de eval PT-BR"},{"id":"B","text":"Ignorar — usuário deve falar inglês"},{"id":"C","text":"Traduzir todas as queries para inglês, gerar em inglês, e traduzir de volta — sempre"},{"id":"D","text":"Comprar mais GPU"}]'::jsonb, 'A',
  '{
    "summary": "Qualidade em idioma minoritário melhora com escolha de modelo + fine-tune + prompt design + eval no idioma.",
    "whyCorrect": "Combinação multi-camada: (1) modelos modernos como Nova e Claude têm forte multilingual; (2) fine-tune com corpus PT-BR ajusta nuances; (3) prompts em PT-BR ativam padrões linguísticos corretos; (4) eval em PT-BR garante medição correta.",
    "whyWrong": {
     "B": "Inaceitável — descumpre proposta de produto.",
     "C": "Round-trip translation degrada (perda de nuance, custo dobrado, latência dobrada).",
     "D": "GPU não muda qualidade linguística do modelo treinado."
    },
    "keyConcept": "Suporte multilíngue em LLMs — model choice + fine-tune + prompt + eval",
    "compareWith": [
     "Round-trip translation vs nativo multilíngue",
     "Fine-tune PT-BR custo/benefício"
    ],
    "realWorldContext": "Bancos brasileiros e fintechs investem em fine-tune PT-BR de modelos abertos para melhor performance local.",
    "commonMistakes": "Aceitar ''qualidade inferior em PT-BR'' como inevitável — várias técnicas mitigam.",
    "tutorSeeds": [
     "Modelos com melhor performance em PT-BR?",
     "Datasets de eval em português (ENEM, BLUEX)?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["multilingual","pt-br","model-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
