INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-034', 'aws-aif', 'Em um pipeline RAG, você descobre que respostas estão FACTUALMENTE corretas mas usam linguagem MUITO TÉCNICA para usuário leigo. Qual ajuste é o mais cirúrgico?',
  '[{"id":"A","text":"Trocar todo o stack para outro vendor"},{"id":"B","text":"Ajustar o prompt do generator para incluir persona ''explique como para um leigo'' + temperature + few-shot exemplos no tom desejado"},{"id":"C","text":"Re-indexar com chunks menores"},{"id":"D","text":"Fine-tunar o modelo com dataset proprietário"}]'::jsonb, 'B',
  '{
    "summary": "Problema de TOM/REGISTRO se resolve com prompt engineering + few-shots — menor esforço, maior ROI.",
    "whyCorrect": "Persona explícita (''Explique como para um leigo, sem jargões''), few-shots mostrando o tom desejado, e temperature ligeiramente maior para fluidez resolvem questão de registro com mínima intervenção.",
    "whyWrong": {
     "A": "Trocar vendor é movimento desproporcional — o problema não é o modelo.",
     "C": "Chunks menores afetam recall do retrieval, não o tom da resposta.",
     "D": "Fine-tune é solução cara para algo que prompt resolve em 1 hora."
    },
    "keyConcept": "Prompt engineering para controle de tom/registro — persona, few-shot, temperature",
    "compareWith": [
     "Prompt engineering vs fine-tuning para style",
     "Custo de intervenção em ordem crescente"
    ],
    "realWorldContext": "Customização leve de tom em chatbots de saúde/jurídico — sempre começar por prompt.",
    "commonMistakes": "Pular direto para fine-tune sem testar prompt engineering primeiro.",
    "tutorSeeds": [
     "Quantos few-shots são ideais?",
     "Como escolher persona em prompt?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'troubleshoot', '["prompt-engineering","persona","tone"]'::jsonb, 'ai-draft', 'active', now(), now()
)
