INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-035', 'aws-aif', 'Sobre ''KV cache'' (prompt cache) em chamadas LLM, é VERDADE que:',
  '[{"id":"A","text":"Ele só funciona com modelos open-source"},{"id":"B","text":"Ele é o mesmo que vector store"},{"id":"C","text":"Ele é eficaz quando muitas chamadas COMPARTILHAM um prefixo grande (system prompt, few-shots fixos)"},{"id":"D","text":"Ele cresce indefinidamente sem TTL"}]'::jsonb, 'C',
  '{
    "summary": "Prompt caching tem ROI alto quando o PREFIXO compartilhado é grande e estável entre chamadas.",
    "whyCorrect": "Sistemas com system prompt longo + few-shots fixos + variação só no user message são candidatos ideais: prefixo cacheável é grande (ex: 8k tokens) e reutilizado em milhões de chamadas.",
    "whyWrong": {
     "A": "Anthropic e OpenAI oferecem prompt caching em modelos managed.",
     "B": "Vector store é retrieval (RAG); prompt cache é reuso de cálculo interno do transformer.",
     "D": "Cache tem TTL (Anthropic: 5min ou 1h; OpenAI: ~5min automatic) — não cresce sem limite."
    },
    "keyConcept": "Prompt caching — economia em prefixos compartilhados",
    "compareWith": [
     "Prompt caching Anthropic vs OpenAI vs Bedrock",
     "TTL configurável vs automatic"
    ],
    "realWorldContext": "RAG apps com system prompt + few-shots de 5k tokens economizam 80% no custo dos tokens IN com prompt caching.",
    "commonMistakes": "Esquecer que prompts mutáveis no início quebram o cache (cache hit precisa de prefixo idêntico).",
    "tutorSeeds": [
     "Como estruturar prompt para maximizar cache hit?",
     "Quando NÃO vale a pena cachear?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["prompt-caching","kv-cache","cost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
