INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-036', 'aws-aif', 'Você tem um workflow com 5 LLM calls em sequência. Qual otimização é mais provável de melhorar latência DRASTICAMENTE?',
  '[{"id":"A","text":"Trocar todos para o modelo XL"},{"id":"B","text":"Adicionar mais 3 steps de validação"},{"id":"C","text":"Mudar a linguagem de programação do backend"},{"id":"D","text":"Paralelizar os steps que não dependem entre si + usar streaming para o step final + cache de resultados intermediários determinísticos"}]'::jsonb, 'D',
  '{
    "summary": "Latência de chains LLM cai com paralelismo + streaming + cache, não com modelo maior.",
    "whyCorrect": "Steps independentes (ex: 3 lookups de tools) podem rodar em paralelo. Streaming do step final reduz time-to-first-token percebido. Cache de steps determinísticos (mesma input → mesma output) elimina chamadas repetidas. Combinados, podem cortar latência em 50-80%.",
    "whyWrong": {
     "A": "Modelo XL é MAIS LENTO por chamada — piora latência.",
     "B": "Adicionar steps aumenta latência.",
     "C": "Linguagem do backend não é o gargalo — gargalo é network + inference time."
    },
    "keyConcept": "Latency optimization em chains — parallelism, streaming, caching",
    "compareWith": [
     "Sequential vs parallel steps",
     "TTFT vs total time"
    ],
    "realWorldContext": "LangChain LCEL e Bedrock Flows permitem paralelizar steps facilmente.",
    "commonMistakes": "Otimizar prematuramente trocando modelo antes de paralelizar.",
    "tutorSeeds": [
     "Como identificar steps paralelizáveis em chain?",
     "Quando streaming não ajuda?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["latency-optimization","parallelism","streaming"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
