INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-037', 'aws-aif', 'Numa matriz cost × latency × quality, qual cenário tipicamente PRIORIZA QUALIDADE acima dos outros dois?',
  '[{"id":"A","text":"Análise jurídica de contratos complexos (decisões críticas, ~10/dia)"},{"id":"B","text":"Sugestões de auto-complete em IDE (1000 sugestões/min/dev)"},{"id":"C","text":"Notificações de marketing massa (1M/dia)"},{"id":"D","text":"Classificação de spam (100M/dia)"}]'::jsonb, 'A',
  '{
    "summary": "Decisões críticas, baixo volume e alto valor por decisão = priorize qualidade (use modelo XL).",
    "whyCorrect": "Análise jurídica de contratos: erro custa caro (litígio, multa), volume baixo (~10/dia diminui pressão de custo), latência aceitável (revisão humana após). Use Opus/o1, prompt elaborado, e até multi-pass com self-critique.",
    "whyWrong": {
     "B": "Auto-complete em IDE prioriza LATÊNCIA (precisa ser <300ms) — modelo S/M ajustado para speed.",
     "C": "Marketing prioriza CUSTO (volume massivo) — modelo S barato.",
     "D": "Spam prioriza CUSTO e LATÊNCIA — classificador especializado/pequeno."
    },
    "keyConcept": "Cost × Latency × Quality matrix — qual eixo priorizar depende do caso de uso",
    "compareWith": [
     "High-stakes low-volume vs low-stakes high-volume",
     "Quality-first vs cost-first"
    ],
    "realWorldContext": "Auditoria de contratos, diagnóstico médico assistido, análise de M&A — sempre quality-first.",
    "commonMistakes": "Usar modelo top em tudo (overspend) ou modelo barato em decisões críticas (underspend on risk).",
    "tutorSeeds": [
     "Como mapear caso de uso à matriz CLQ?",
     "Self-critique para boost de quality?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["tradeoff","use-case-matching","quality-first"]'::jsonb, 'ai-draft', 'active', now(), now()
)
