INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-038', 'aws-aif', 'Para uma aplicação MISSION CRITICAL, qual estratégia de DEPLOY de novo MODELO (não só prompt) é a mais segura?',
  '[{"id":"A","text":"Trocar 100% de uma vez"},{"id":"B","text":"Shadow deploy (nova versão recebe cópia do tráfego sem responder ao usuário) → comparar com produção → canary 1%/5%/25%/100% → monitorar métricas de qualidade + operação"},{"id":"C","text":"Deploy só na sexta-feira à tarde"},{"id":"D","text":"Avisar usuários por email e fazer o switch"}]'::jsonb, 'B',
  '{
    "summary": "Shadow → canary gradual + monitoring é o padrão para deploy seguro de modelos em apps mission critical.",
    "whyCorrect": "Shadow expõe modelo novo a tráfego real sem afetar usuários — compara métricas paralelamente. Canary aumenta exposição gradualmente. Monitoring captura sinais cedo. Rollback é instantâneo se algo degrada.",
    "whyWrong": {
     "A": "Big-bang é arriscado em mission critical — sem dados reais para validar.",
     "C": "Deploy sexta tarde é antipattern conhecido — equipe de plantão indisponível.",
     "D": "Avisar usuários não substitui validação técnica."
    },
    "keyConcept": "Safe deploy patterns — Shadow + Canary + Monitoring + Rollback",
    "compareWith": [
     "Shadow vs Canary",
     "Blue/Green vs Canary"
    ],
    "realWorldContext": "Google, Netflix, Stripe usam shadow deploy para mudanças de ML em produção.",
    "commonMistakes": "Pular shadow e ir direto para canary com 25% — exposição cedo demais.",
    "tutorSeeds": [
     "Como implementar shadow deploy em LLM?",
     "Métricas para gate de canary promotion?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'best-practice', '["shadow-deploy","canary","mission-critical"]'::jsonb, 'ai-draft', 'active', now(), now()
)
