INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-039', 'aws-aif', 'Sobre escolha entre TEXT-ONLY e MULTIMODAL model para um caso de uso, qual afirmação é mais CORRETA?',
  '[{"id":"A","text":"Multimodal sempre vence porque processa mais modalidades"},{"id":"B","text":"Text-only e multimodal têm o mesmo custo"},{"id":"C","text":"Use text-only quando inputs são puramente textuais (custa menos, mais rápido em texto puro); use multimodal quando inputs incluem imagens/áudio/vídeo OU layout visual é informação relevante"},{"id":"D","text":"Multimodal só serve para imagens, não para vídeo ou áudio"}]'::jsonb, 'C',
  '{
    "summary": "Escolha modalidade pelo conteúdo real do input; multimodal só quando há sinal não-textual relevante.",
    "whyCorrect": "Multimodal é mais caro e geralmente mais lento que text-only. Usar multimodal quando input é texto puro é desperdício. Por outro lado, quando layout visual ou imagens contêm informação, modalidades visuais são essenciais.",
    "whyWrong": {
     "A": "Multimodal NÃO ''sempre vence'' — para texto puro, modelo text-only equivalente é melhor em custo/latência.",
     "B": "Multimodal cobra tokens diferentes para imagens (geralmente mais caros que text tokens).",
     "D": "Modelos multimodais modernos (Claude, Gemini, GPT-4o, Nova) processam imagens, vídeo, áudio."
    },
    "keyConcept": "Modality selection — escolher pelo input real, não pela disponibilidade",
    "compareWith": [
     "Text-only vs Multimodal — custo de tokens",
     "Quando vídeo/áudio justifica multimodal"
    ],
    "realWorldContext": "Apps que processam só JSON/texto não deveriam usar modelos multimodais por default.",
    "commonMistakes": "Default para multimodal ''porque é mais novo'' — ignora trade off de custo/latência.",
    "tutorSeeds": [
     "Custo por imagem em Claude/GPT-4o?",
     "Quando áudio direto é melhor que transcrever para texto?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'medium', 'scenario', '["multimodal","modality-choice","tradeoff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
