INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-genai-v3-040', 'aws-aif', 'Você precisa decidir entre Provisioned Throughput e On-demand no Bedrock para a inferência. Qual cenário JUSTIFICA Provisioned Throughput?',
  '[{"id":"A","text":"Cargas imprevisíveis, baixo volume, sem SLA estrito"},{"id":"B","text":"Experimentos de prototipagem"},{"id":"C","text":"Nunca — on-demand é sempre melhor"},{"id":"D","text":"Cargas estáveis e altas, com SLA de latência exigente e necessidade de capacidade GARANTIDA — análise de break-even mostra economia vs on-demand"}]'::jsonb, 'D',
  '{
    "summary": "Provisioned Throughput vale quando: carga estável + alta + SLA + break-even financeiro favorável.",
    "whyCorrect": "Provisioned Throughput reserva capacidade dedicada (cobrança horária previsível), elimina throttling, garante latência. Faz sentido em cargas estáveis e altas, onde custo/hora < custo equivalente em on-demand. Em cargas baixas/imprevisíveis, on-demand é mais econômico.",
    "whyWrong": {
     "A": "On-demand vence para cargas imprevisíveis/baixas.",
     "B": "Protótipos não justificam reserva paga.",
     "C": "On-demand não é sempre melhor — em escala e SLA, Provisioned vence."
    },
    "keyConcept": "Provisioned Throughput vs On-demand — break-even análise de carga e SLA",
    "compareWith": [
     "Bedrock Provisioned Throughput vs On-demand",
     "Reserved instance vs On-demand pattern"
    ],
    "realWorldContext": "Apps com 1M+ chamadas/dia estáveis frequentemente migram para Provisioned para garantir SLA + reduzir custo.",
    "commonMistakes": "Comprar Provisioned ''por segurança'' sem análise — pagar capacidade ociosa é desperdício.",
    "tutorSeeds": [
     "Como calcular break-even Provisioned vs On-demand?",
     "Provisioned model units no Bedrock?"
    ]
   }'::jsonb,
  'Fundamentals of Generative AI', 'Fundamentals of Generative AI', 'hard', 'scenario', '["provisioned-throughput","on-demand","cost-tradeoff","bedrock"]'::jsonb, 'ai-draft', 'active', now(), now()
)
