INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-001', 'aws-aif', 'Quais são características de IA responsável segundo o guia oficial?',
  '[{"id":"A","text":"Viés, justiça, inclusividade, robustez, segurança e veracidade"},{"id":"B","text":"Velocidade, custo baixo e escalabilidade"},{"id":"C","text":"Alta acurácia e baixa latência"},{"id":"D","text":"Código aberto e licença permissiva"}]'::jsonb, 'A',
  '{
    "summary": "O enunciado 4.1 lista nominalmente as características de IA responsável.",
    "whyCorrect": "Viés, justiça, inclusividade, robustez, segurança e veracidade são os eixos que o guia nomeia — e nenhum deles é medido pelas métricas usuais de desempenho, o que é justamente o ponto do domínio.",
    "whyWrong": {
     "B": "Velocidade, custo e escala são atributos operacionais legítimos e ortogonais à responsabilidade: um sistema rápido e barato pode ser profundamente injusto.",
     "C": "Acurácia e latência medem desempenho. Um modelo de alta acurácia média pode errar sistematicamente contra um grupo, e a média esconde exatamente isso.",
     "D": "Abertura de código e licença tocam transparência e são um MEIO, não o conjunto de características que o guia define como IA responsável."
    },
    "keyConcept": "Características de IA responsável"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
