INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-002', 'aws-aif', 'Um modelo de triagem de currículos aprova 82% dos candidatos de um grupo e 41% de outro, com desempenho médio alto. Que ferramenta da AWS ajuda a detectar e quantificar isso?',
  '[{"id":"A","text":"Amazon CloudWatch Logs"},{"id":"B","text":"Amazon SageMaker Clarify"},{"id":"C","text":"AWS Cost Explorer"},{"id":"D","text":"Amazon Athena"}]'::jsonb, 'B',
  '{
    "summary": "Clarify é a ferramenta que o guia nomeia para detecção de viés antes e depois do treino.",
    "whyCorrect": "O Clarify calcula métricas de viés por subgrupo, antes do treinamento sobre o conjunto e depois sobre as previsões do modelo — que é exatamente a análise que a diferença de 41 pontos exige.",
    "whyWrong": {
     "A": "CloudWatch Logs guarda registro operacional: erro, latência, invocação. Ele mostraria que o modelo respondeu, nunca que respondeu de forma desigual entre grupos.",
     "C": "Cost Explorer analisa gasto na conta. É a alternativa que testa se o candidato associa \"análise\" a qualquer ferramenta analítica da AWS.",
     "D": "Athena consulta dados no S3 e poderia calcular a diferença à mão, com muito trabalho. O guia pede a ferramenta dedicada, que já traz as métricas de justiça prontas e comparáveis."
    },
    "keyConcept": "SageMaker Clarify e detecção de viés",
    "realWorldContext": "Crédito, seleção de pessoal e precificação são onde a diferença entre grupos vira risco jurídico."
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
