INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-003', 'aws-aif', 'Quais são riscos LEGAIS de trabalhar com IA generativa que o guia cita?',
  '[{"id":"A","text":"Apenas o custo excessivo de inferência"},{"id":"B","text":"Somente indisponibilidade do serviço"},{"id":"C","text":"Violação de propriedade intelectual, saída enviesada, perda de confiança do cliente, risco ao usuário final e alucinação"},{"id":"D","text":"Somente vazamento de credencial da conta"}]'::jsonb, 'C',
  '{
    "summary": "O enunciado 4.1 lista explicitamente os riscos legais da GenAI.",
    "whyCorrect": "Violação de propriedade intelectual, viés na saída, perda de confiança, risco ao usuário final e alucinação são os riscos nomeados — e todos podem virar processo, não apenas incidente técnico.",
    "whyWrong": {
     "A": "Custo é risco financeiro e operacional; ninguém é processado por gastar demais com inferência.",
     "B": "Indisponibilidade é risco de disponibilidade, tratado por arquitetura e acordo de nível de serviço, não por diretriz de IA responsável.",
     "D": "Vazamento de credencial é risco de segurança clássico, coberto pelo domínio 5 — importante, e não é o que a pergunta isola."
    },
    "keyConcept": "Riscos legais da IA generativa"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
