INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-004', 'aws-aif', 'Para que serve um SageMaker Model Card?',
  '[{"id":"A","text":"Acelerar a inferência do modelo"},{"id":"B","text":"Cifrar os pesos do modelo"},{"id":"C","text":"Reduzir o custo de armazenamento do artefato"},{"id":"D","text":"Documentar propósito, dados de treino, métricas, limitações e uso pretendido do modelo, num artefato versionado"}]'::jsonb, 'D',
  '{
    "summary": "Model Card é o artefato de transparência que o guia nomeia.",
    "whyCorrect": "Ele registra para que o modelo foi feito, com que dado foi treinado, como se sai nas métricas e onde NÃO deve ser usado — a documentação que uma auditoria pede e que a memória de pessoas não sustenta.",
    "whyWrong": {
     "A": "Desempenho de inferência depende de infraestrutura e modo de implantação; documentação não muda tempo de resposta.",
     "B": "Cifra de artefato é responsabilidade do KMS e da configuração de armazenamento, e não tem relação com documentar.",
     "C": "O cartão é um documento pequeno ao lado do artefato do modelo; ele acrescenta bytes em vez de economizar."
    },
    "keyConcept": "SageMaker Model Cards"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
