INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-005', 'aws-aif', 'Qual é o trade-off que o guia pede para reconhecer entre segurança e transparência de um modelo?',
  '[{"id":"A","text":"Modelos mais interpretáveis costumam entregar desempenho menor que os mais complexos, e a escolha depende do que o caso exige"},{"id":"B","text":"Não existe trade-off: transparência sempre melhora tudo"},{"id":"C","text":"Transparência aumenta a latência de inferência"},{"id":"D","text":"Modelos transparentes não podem ser implantados na nuvem"}]'::jsonb, 'A',
  '{
    "summary": "O guia pede identificar o trade-off entre interpretabilidade e desempenho.",
    "whyCorrect": "Uma regressão logística explica cada decisão e costuma perder em desempenho para um conjunto de árvores ou uma rede profunda. Em setor regulado a explicabilidade vence; em recomendação de catálogo, geralmente não.",
    "whyWrong": {
     "B": "Negar o trade-off leva a exigir explicabilidade onde ela custa desempenho sem trazer benefício — ou a abrir mão dela onde é obrigatória.",
     "C": "Interpretabilidade é propriedade da estrutura do modelo, não do tempo de resposta; modelos simples costumam ser até mais rápidos.",
     "D": "Não há restrição de implantação: modelos interpretáveis rodam nos mesmos endpoints que qualquer outro."
    },
    "keyConcept": "Interpretabilidade vs desempenho"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
