INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-006', 'aws-aif', 'Uma equipe quer inserir revisão humana nas previsões de baixa confiança de um modelo de extração de documentos. Que serviço da AWS foi feito para isso?',
  '[{"id":"A","text":"AWS Step Functions"},{"id":"B","text":"Amazon Augmented AI (A2I)"},{"id":"C","text":"Amazon SQS"},{"id":"D","text":"AWS Batch"}]'::jsonb, 'B',
  '{
    "summary": "O guia lista o A2I entre as ferramentas de monitoramento de confiabilidade.",
    "whyCorrect": "O A2I insere fluxo de revisão humana no caminho da inferência, encaminhando ao revisor os casos que caem abaixo do limiar de confiança e devolvendo o resultado corrigido.",
    "whyWrong": {
     "A": "Step Functions orquestra estados e poderia coordenar um fluxo de revisão que você construísse inteiro à mão — interface de revisor, fila de trabalho e agregação de resultado incluídas.",
     "C": "SQS transporta mensagem entre componentes; ela seria uma peça dentro da solução, sem oferecer nada de revisão humana.",
     "D": "Batch executa trabalho em lote em contêiner: é capacidade de computação, e o que falta no cenário é intervenção HUMANA. Escolher aqui vem de ler \"casos de baixa confiança\" como um lote a reprocessar, quando o que se quer é uma pessoa decidindo."
    },
    "keyConcept": "Amazon A2I e humano no laço"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
