INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-007', 'aws-aif', 'Que característica de CONJUNTO DE DADOS o guia associa a IA responsável?',
  '[{"id":"A","text":"Volume máximo, independentemente da origem"},{"id":"B","text":"Formato colunar e compressão"},{"id":"C","text":"Inclusividade, diversidade, fontes curadas e equilíbrio entre classes e grupos"},{"id":"D","text":"Armazenamento em região única"}]'::jsonb, 'C',
  '{
    "summary": "O enunciado 4.1 lista as características de um conjunto responsável.",
    "whyCorrect": "Inclusividade, diversidade, curadoria da fonte e equilíbrio determinam se o modelo aprende o padrão de todos ou apenas o do grupo mais representado no dado.",
    "whyWrong": {
     "A": "Volume sem curadoria amplifica o viés já presente na fonte — mais dado enviesado produz um modelo mais confiantemente enviesado.",
     "B": "Formato e compressão são decisões de engenharia de dados que afetam custo e velocidade, e nada dizem sobre justiça.",
     "D": "Região de armazenamento é assunto de residência de dado e conformidade, do domínio 5, e não característica de qualidade do conjunto."
    },
    "keyConcept": "Características de conjunto de dados responsável"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
