INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-008', 'aws-aif', 'O que os princípios de projeto centrado no humano para IA explicável recomendam?',
  '[{"id":"A","text":"Esconder do usuário que há IA envolvida, para não gerar desconfiança"},{"id":"B","text":"Exigir que todo usuário entenda o algoritmo"},{"id":"C","text":"Substituir a decisão humana em todos os casos"},{"id":"D","text":"Deixar claro quando uma decisão vem de IA e oferecer mecanismo de retorno do usuário"}]'::jsonb, 'D',
  '{
    "summary": "O guia lista transparência da decisão e mecanismo de retorno entre os princípios.",
    "whyCorrect": "Dizer que a decisão veio de um sistema de IA e dar ao usuário um caminho para contestar ou corrigir é o que torna o sistema auditável na prática — e o retorno vira insumo de melhoria.",
    "whyWrong": {
     "A": "Esconder é o oposto de transparência e, quando descoberto, produz exatamente a perda de confiança que o domínio 4 lista como risco.",
     "B": "Exigir que o usuário entenda o algoritmo transfere a ele um ônus impossível; a obrigação é explicar a DECISÃO em termos que ele compreenda.",
     "C": "Automatizar tudo remove o humano do laço justamente onde ele mais importa — nos casos de baixa confiança e de alto impacto."
    },
    "keyConcept": "Projeto centrado no humano para IA explicável"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
