INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-responsible-ai-v1-009', 'aws-aif', 'Além de custo e desempenho, que consideração o guia inclui entre as práticas responsáveis de ESCOLHA de modelo?',
  '[{"id":"A","text":"Considerações ambientais e de sustentabilidade"},{"id":"B","text":"A popularidade do modelo entre desenvolvedores"},{"id":"C","text":"A quantidade de idiomas suportados"},{"id":"D","text":"O tamanho da comunidade de suporte"}]'::jsonb, 'A',
  '{
    "summary": "O enunciado 4.1 cita explicitamente sustentabilidade na seleção de modelo.",
    "whyCorrect": "Modelos maiores consomem mais energia por inferência. Escolher o menor modelo que atende ao requisito é decisão responsável, além de econômica — os dois eixos apontam para o mesmo lado.",
    "whyWrong": {
     "B": "Popularidade não é critério de responsabilidade nem de adequação técnica; ela mede adoção, que pode vir de marketing.",
     "C": "Suporte a idiomas é critério funcional legítimo de seleção, listado no domínio 3, e não uma consideração de responsabilidade.",
     "D": "Tamanho de comunidade ajuda na operação do dia a dia e não diz nada sobre impacto ambiental ou justiça."
    },
    "keyConcept": "Sustentabilidade na escolha de modelo"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
