INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-001', 'aws-aif', 'Uma empresa exige que o tráfego entre a aplicação e o Bedrock não saia para a internet pública. Que recurso atende?',
  '[{"id":"A","text":"AWS PrivateLink com endpoint de VPC"},{"id":"B","text":"Amazon CloudFront"},{"id":"C","text":"AWS Shield"},{"id":"D","text":"Amazon Route 53 Resolver"}]'::jsonb, 'A',
  '{
    "summary": "O guia lista o PrivateLink entre os recursos de segurança de sistemas de IA.",
    "whyCorrect": "O PrivateLink cria um endpoint na sua VPC, e a chamada ao serviço passa a trafegar pela rede da AWS sem sair para a internet pública — que é exatamente o requisito.",
    "whyWrong": {
     "B": "CloudFront é rede de entrega de conteúdo, feita para aproximar conteúdo do usuário na BORDA pública. Ele resolve o problema oposto do enunciado.",
     "C": "Shield protege contra negação de serviço distribuída. É proteção de disponibilidade e não altera por onde o tráfego trafega.",
     "D": "O Route 53 Resolver trata de resolução de DNS entre redes; ele ajuda a resolver o nome do endpoint, e não é o que cria o caminho privado."
    },
    "keyConcept": "PrivateLink e caminho privado de rede"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
