INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-002', 'aws-aif', 'Que serviço da AWS descobre e classifica dados sensíveis armazenados no S3, como informação pessoal?',
  '[{"id":"A","text":"Amazon Inspector"},{"id":"B","text":"Amazon Macie"},{"id":"C","text":"AWS Config"},{"id":"D","text":"Amazon GuardDuty"}]'::jsonb, 'B',
  '{
    "summary": "Cada serviço de segurança da AWS responde a uma pergunta distinta, e a prova cobra o par.",
    "whyCorrect": "O Macie usa aprendizado de máquina para identificar e classificar dado sensível no S3, respondendo \"onde está a informação pessoal no meu lago de dados?\".",
    "whyWrong": {
     "A": "Inspector avalia vulnerabilidade em carga de trabalho — instâncias, contêineres, funções. Ele olha software, não conteúdo de dado.",
     "C": "Config registra e avalia CONFIGURAÇÃO de recurso ao longo do tempo. Ele diria que um bucket está público, sem dizer se há dado pessoal dentro dele.",
     "D": "GuardDuty detecta ameaça e atividade suspeita a partir de registros de rede e API. Ele acusa comportamento anômalo, não classifica conteúdo."
    },
    "keyConcept": "Macie, Inspector, Config e GuardDuty"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
