INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-003', 'aws-aif', 'Um sistema de RAG às vezes responde além do que a fonte recuperada sustenta. Que técnica de ancoragem reduz isso?',
  '[{"id":"A","text":"Aumentar a temperatura para o modelo explorar mais"},{"id":"B","text":"Aumentar o tamanho do fragmento indefinidamente"},{"id":"C","text":"Verificação de ancoragem contextual, recusando resposta que não se apoia no trecho recuperado"},{"id":"D","text":"Remover as citações da resposta para não confundir o usuário"}]'::jsonb, 'C',
  '{
    "summary": "O guia lista métodos de detecção de alucinação e técnicas de ancoragem.",
    "whyCorrect": "A verificação de ancoragem compara a resposta com o material recuperado e bloqueia ou sinaliza o que não se sustenta nele — é o controle direto contra a alucinação em RAG, e o Bedrock Guardrails oferece isso como política.",
    "whyWrong": {
     "A": "Temperatura alta aumenta a variação da amostragem e, com isso, a chance de o modelo se afastar da fonte. É a alternativa que piora exatamente o problema descrito.",
     "B": "Fragmento maior traz mais conteúdo e também mais ruído, diluindo o sinal; ele não impede o modelo de afirmar o que não está lá.",
     "D": "Remover a citação apaga a única forma de o leitor verificar a afirmação — troca o sintoma visível por um problema invisível."
    },
    "keyConcept": "Ancoragem contextual e detecção de alucinação"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
