INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-004', 'aws-aif', 'Uma auditoria pede a lista de quem chamou qual API da AWS, quando e a partir de onde, nos últimos 90 dias. Que serviço fornece isso?',
  '[{"id":"A","text":"Amazon CloudWatch Metrics"},{"id":"B","text":"AWS Trusted Advisor"},{"id":"C","text":"AWS Artifact"},{"id":"D","text":"AWS CloudTrail"}]'::jsonb, 'D',
  '{
    "summary": "A prova separa registro de chamada de API, métrica, recomendação e relatório de conformidade.",
    "whyCorrect": "O CloudTrail registra as chamadas de API da conta com identidade, horário, origem e parâmetros — é a trilha de auditoria por definição.",
    "whyWrong": {
     "A": "CloudWatch Metrics guarda séries numéricas de desempenho e utilização. Ele mostra quanto foi chamado, nunca por quem.",
     "B": "Trusted Advisor recomenda melhorias de custo, desempenho e segurança. É conselho sobre o estado atual, não histórico de ações.",
     "C": "Artifact entrega os relatórios de conformidade DA AWS, como SOC e ISO. Ele documenta o provedor, não o que a sua equipe fez."
    },
    "keyConcept": "CloudTrail e trilha de auditoria"
   }'::jsonb,
  '', '', 'easy', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
