INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-005', 'aws-aif', 'O que trata a residência de dados numa estratégia de governança?',
  '[{"id":"A","text":"Em qual território geográfico o dado é armazenado e processado"},{"id":"B","text":"O tempo que o dado é retido antes de ser apagado"},{"id":"C","text":"O formato de arquivo em que o dado é gravado"},{"id":"D","text":"Quem tem permissão de leitura sobre o dado"}]'::jsonb, 'A',
  '{
    "summary": "O guia lista residência entre as estratégias de governança de dado.",
    "whyCorrect": "Residência é a exigência de que o dado permaneça em determinada jurisdição — o que restringe as regiões onde a carga pode rodar e frequentemente elimina opções de serviço antes de qualquer avaliação técnica.",
    "whyWrong": {
     "B": "Tempo até o descarte é RETENÇÃO, também listada no guia, e é uma dimensão diferente: quando apagar, e não onde guardar.",
     "C": "Formato é decisão de engenharia sobre custo e desempenho de leitura, sem relação com jurisdição.",
     "D": "Quem pode ler é controle de acesso. Um dado pode ter permissão perfeita e ainda assim violar residência por estar na região errada."
    },
    "keyConcept": "Residência, retenção e ciclo de vida do dado"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
