INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-006', 'aws-aif', 'Que prática protege contra vazamento de dado sensível na SAÍDA de um modelo?',
  '[{"id":"A","text":"Cifrar o volume da instância de treinamento"},{"id":"B","text":"Filtro e validação de saída, incluindo mascaramento ou bloqueio de informação pessoal"},{"id":"C","text":"Aumentar o número de tokens da resposta"},{"id":"D","text":"Usar um modelo maior"}]'::jsonb, 'B',
  '{
    "summary": "O guia cita filtragem e validação de saída entre as considerações de segurança.",
    "whyCorrect": "A saída precisa passar por um controle que detecte e trate informação pessoal antes de chegar ao usuário — mascarando ou bloqueando, conforme a política. O Bedrock Guardrails oferece as duas ações.",
    "whyWrong": {
     "A": "Cifrar o volume protege o dado em REPOUSO contra acesso ao disco. Ele não impede que o modelo escreva um CPF na resposta.",
     "C": "Aumentar o tamanho da resposta não tem relação com o conteúdo dela — no limite, dá mais espaço para vazar mais.",
     "D": "Modelo maior pode ser mais capaz e não é um controle de segurança; ele vaza com mais fluência se nada filtrar a saída."
    },
    "keyConcept": "Filtragem e validação de saída"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
