INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-007', 'aws-aif', 'O que é a Matriz de Escopo de Segurança para IA Generativa, citada no guia?',
  '[{"id":"A","text":"Um serviço da AWS para cifrar prompts"},{"id":"B","text":"Uma tabela de preços por token"},{"id":"C","text":"Um arcabouço que classifica a solução de GenAI por grau de controle sobre o modelo e o dado, orientando os controles necessários"},{"id":"D","text":"Um relatório de conformidade da AWS"}]'::jsonb, 'C',
  '{
    "summary": "O guia nomeia a matriz entre os arcabouços de governança.",
    "whyCorrect": "A matriz separa os casos por escopo — de consumir uma aplicação pronta até treinar um modelo próprio — porque a responsabilidade de segurança muda radicalmente entre eles, e com ela os controles exigidos.",
    "whyWrong": {
     "A": "Não é serviço, é arcabouço de classificação. A confusão vem de a AWS publicar tanto serviços quanto documentos de orientação.",
     "B": "Preço por token está na página de preços do serviço; a matriz trata de risco e responsabilidade.",
     "D": "Relatório de conformidade é o que o Artifact entrega. A matriz orienta o SEU desenho, e não atesta a conformidade da AWS."
    },
    "keyConcept": "Matriz de Escopo de Segurança para GenAI"
   }'::jsonb,
  '', '', 'hard', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
