INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-008', 'aws-aif', 'Como o modelo de responsabilidade compartilhada se aplica a um serviço gerenciado de IA como o Bedrock?',
  '[{"id":"A","text":"A AWS é responsável por tudo, inclusive pelo conteúdo dos prompts"},{"id":"B","text":"O cliente é responsável por aplicar patch nos servidores de inferência"},{"id":"C","text":"A responsabilidade compartilhada não se aplica a serviços de IA"},{"id":"D","text":"A AWS cuida da segurança DA nuvem; você cuida da segurança NA nuvem — controle de acesso, dado enviado, filtro de saída e uso"}]'::jsonb, 'D',
  '{
    "summary": "A divisão é a mesma de qualquer serviço gerenciado, e o guia a lista no domínio 5.",
    "whyCorrect": "A AWS opera e protege a infraestrutura; você decide quem pode invocar, que dado envia, o que filtra na saída e como registra o uso. É essa metade que produz a maior parte dos incidentes.",
    "whyWrong": {
     "A": "O conteúdo do prompt é escolha sua: enviar dado sensível sem necessidade é decisão do cliente, e nenhum provedor pode impedi-la.",
     "B": "Aplicar patch em servidor de inferência gerenciado é responsabilidade da AWS — é justamente o que se compra ao usar serviço gerenciado.",
     "C": "O modelo vale para todos os serviços; supor exceção para IA é o raciocínio que leva a não implementar controle nenhum."
    },
    "keyConcept": "Responsabilidade compartilhada em serviços de IA"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
