INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'aif-c01-security-governance-v1-009', 'aws-aif', 'Uma equipe precisa rastrear a origem dos dados que alimentaram um modelo, para responder a uma auditoria. Como se chama isso e o que ajuda a sustentá-lo?',
  '[{"id":"A","text":"Linhagem de dados; catalogação e documentação da origem, com Model Cards registrando a procedência"},{"id":"B","text":"Deriva de dados; SageMaker Model Monitor"},{"id":"C","text":"Particionamento; Glue Data Catalog"},{"id":"D","text":"Cifra em repouso; AWS KMS"}]'::jsonb, 'A',
  '{
    "summary": "O guia lista citação de fonte e documentação de origem — linhagem e catalogação.",
    "whyCorrect": "Linhagem é a cadeia que liga o modelo ao dado e ao código que o produziram. Catalogar as fontes e registrar a procedência no cartão do modelo é o que permite responder a auditoria sem reconstruir a história pela memória de pessoas.",
    "whyWrong": {
     "B": "Deriva descreve mudança de distribuição ao longo do tempo, e a pergunta é sobre a ORIGEM do dado, não sobre como ele mudou.",
     "C": "Particionamento organiza o armazenamento para consulta eficiente; o Data Catalog ajuda na descoberta e não registra por si só a cadeia até o modelo treinado.",
     "D": "Cifra em repouso protege confidencialidade e nada informa sobre a procedência do que está cifrado."
    },
    "keyConcept": "Linhagem de dados e procedência"
   }'::jsonb,
  '', '', 'medium', NULL, '[]'::jsonb, NULL, 'active', now(), now()
)
